  '18–24 aydan küçüklerde görüntülü görüşme dışında ekran önerilmez.': 'صفحه‌نمایش زیر ۱۸–۲۴ ماهگی توصیه نمی‌شود، جز تماس تصویری.',
  '1–2 yaş: 11–14 saat; 3–5 yaş: 10–13 saat (şekerlemeler dahil) önerilir.': 'توصیه: ۱–۲ سالگی ۱۱–۱۴ ساعت؛ ۳–۵ سالگی ۱۰–۱۳ ساعت (با چرت).',
  '1–2 yılda bir; görme değişikliği varsa daha erken.': 'هر ۱ تا ۲ سال؛ اگر بینایی‌تان تغییر کرد زودتر.',
