  '2 yaşında iki kelimeli cümleler kurmaya başlar, koşar, top atar.': 'در ۲ سالگی جمله‌های دوکلمه‌ای می‌سازند، می‌دوند و توپ پرتاب می‌کنند.',
  '2 yaşında iki kelimeli ifadeler kuramama, yönergeleri anlamama.': 'نساختن عبارت دوکلمه‌ای یا نفهمیدن دستورها در ۲ سالگی.',
