  '2 yumurta': '۲ تخم‌مرغ',
  '2. ay: sosyal gülümseme, seslere tepki, yüzleri izleme.': '۲ ماهگی: لبخند اجتماعی، واکنش به صداها، نگاه کردن به چهره‌ها.',
  '2. hafta: Dinlenme ve beslenme düzenini gözden geçirin. Emzirme veya besleme güçlüğünde destek isteyin.': 'هفته ۲: برنامه استراحت و غذا خوردن را مرور کنید. اگر در شیردهی یا تغذیه مشکل دارید کمک بخواهید.',
  '2. trimester': 'سه‌ماهه دوم',
  '200 g beyaz peynir': '۲۰۰ گرم پنیر سفید',
  '200 g kıyma': '۲۰۰ گرم گوشت چرخ‌کرده',
  '200 g rendelenmiş mozzarella': '۲۰۰ گرم موتزارلای رنده‌شده',
  '200 g tavuk göğsü': '۲۰۰ گرم سینه‌ی مرغ',
  '200 ml sıvı krema (veya 1 su bardağı süt + 1 yemek kaşığı un)': '۲۰۰ میلی‌لیتر خامه‌ی پخت (یا ۱ لیوان شیر + ۱ قاشق غذاخوری آرد)',
  '200°C fırında yaklaşık 20–25 dakika, iç sıcaklık 74°C’ye ulaşana kadar pişirin.': 'در فر ۲۰۰ درجه حدود ۲۰–۲۵ دقیقه بپزید تا دمای داخلی به ۷۴ درجه برسد.',
  '20–39 yaş arası 1–3 yılda bir, 40 yaştan sonra yılda bir.': 'هر ۱ تا ۳ سال بین ۲۰ تا ۳۹ سالگی، و پس از ۴۰ سالگی هر سال.',
  '24 saatten uzun hiçbir şey tutamama, idrar azalması, baş dönmesi.': 'بیش از ۲۴ ساعت چیزی نگه نداشتن، ادرار کمتر، سرگیجه.',
  '24–28. haftalar arasında şeker yükleme testiyle taranır.': 'با آزمون تحمل گلوکز بین هفته‌های ۲۴ تا ۲۸ غربالگری می‌شود.',
  '24–28. haftalarda gebelik diyabeti taraması (şeker yükleme testi) önerilir.': 'غربالگری دیابت بارداری (آزمون تحمل گلوکز) در هفته‌های ۲۴–۲۸ توصیه می‌شود.',
  '250 g erişte': '۲۵۰ گرم رشته‌ی خانگی',
  '250 g fırın makarna': '۲۵۰ گرم ماکارونی فری',
  '250 g makarna': '۲۵۰ گرم ماکارونی',
  '250 g mantar': '۲۵۰ گرم قارچ',
  '250 g somon fileto (derisiz, küp doğranmış)': '۲۵۰ گرم فیله‌ی سالمون (بدون پوست، مکعبی)',
  '28. haftadan sonra, bebeğin genelde hareketli olduğu bir saatte yan yatarak başla. Her tekme, dönme ya da kıpırtıda dokun; 10 harekete kaç dakikada ulaştığını görürsün.': 'بعد از هفته ۲۸، زمانی که کودک معمولاً فعال است به پهلو دراز بکشید. با هر لگد، چرخش یا تکان بزنید؛ خواهید دید رسیدن به ۱۰ حرکت چند دقیقه طول می‌کشد.',
  '2–3 yaş: cümleleri uzar, renkleri ve şekilleri öğrenmeye başlar, "neden?" soruları çoğalır. Bağımsız giyinmeyi dener.': '۲–۳ سالگی: جمله‌ها بلندتر می‌شوند، رنگ‌ها و اشکال را یاد می‌گیرد، زیاد «چرا؟» می‌پرسد. سعی می‌کند خودش لباس بپوشد.',
  '2–5 yaş için günde en fazla 1 saat, yaşa uygun ve mümkünse birlikte izlenen içerik önerilir.': 'برای ۲–۵ سالگی حداکثر ۱ ساعت در روز محتوای مناسب سن، ترجیحاً با هم تماشا کردن، توصیه می‌شود.',
  '3 adet yufka': '۳ ورق یوفکا',
  '3 ay': '۳ ماه',
  '3 aydan küçük bebekte 38 °C ve üzeri ateş: Bebek iyi görünse bile hemen doktora ya da acile başvur.': 'تب ۳۸ درجه یا بیشتر در نوزاد زیر ۳ ماه: حتی اگر خوب به نظر می‌رسد، فوراً به پزشک یا اورژانس مراجعه کنید.',
  '3 aydan küçük bebekte ateş (koltuk altı 37,5 °C, rektal 38 °C ve üstü) her zaman acil değerlendirme gerektirir.': 'هر تبی در نوزاد زیر ۳ ماه (زیر بغل ۳۷٫۵ °C، مقعدی ۳۸ °C و بالاتر) همیشه نیاز به ارزیابی فوری دارد.',
  '3 aydan küçük bebekte ateş.': 'تب در نوزاد زیر ۳ ماه.',
  '3 aydan küçük bebekte herhangi bir ateş.': 'هر تبی در نوزاد زیر ۳ ماه.',
  '3 aydan uzun adet görmeme (gebelik dışlandıktan sonra).': 'نبود قاعدگی بیش از ۳ ماه (پس از رد بارداری).',
  '3 dal taze kekik veya 1 çay kaşığı kuru kekik': '۳ شاخه آویشن تازه یا ۱ قاشق چای‌خوری آویشن خشک',
  '3 dal taze soğan': '۳ ساقه پیازچه',
  '3 domates': '۳ گوجه‌فرنگی',
  '3 gün içinde son kullanma: {0} • Tarihi geçmiş: {1}': 'تا ۳ روز دیگر منقضی می‌شود: {0} • منقضی شده: {1}',
  '3 günden uzun süren ateş veya kötüleşen genel durum.': 'تب بیش از ۳ روز یا بدتر شدن حال عمومی.',
  '3 kabak': '۳ کدو سبز',
  '3 patates': '۳ سیب‌زمینی',
  '3 su bardağı su': '۳ لیوان آب',
  '3 yaş': '۳ سالگی',
  '3 yaş: 3–4 kelimelik cümleler, merdiven çıkma, hayali oyun.': '۳ سالگی: جمله‌های ۳–۴ کلمه‌ای، بالا رفتن از پله، بازی وانمودی.',
  '3 yaşına kadar pirinç tanesi, 3–6 yaş arası bezelye büyüklüğünde florürlü diş macunu önerilir.': 'تا ۳ سالگی خمیردندان فلورایددار به اندازه‌ی دانه‌ی برنج و از ۳ تا ۶ سالگی به اندازه‌ی نخود توصیه می‌شود.',
  '3 yaşında anlaşılmayan konuşma veya cümle kuramama.': 'گفتار نامفهوم یا نبود جمله در ۳ سالگی.',
