  '3. trimester': 'سه‌ماهه سوم',
  '30 günlük değer yalnızca matematiksel karşılaştırmadır; büyüme tahmini veya tıbbi yorum değildir.': 'مقدار ۳۰ روزه فقط یک مقایسه ریاضی است؛ پیش‌بینی رشد یا تفسیر پزشکی نیست.',
  '30 saniyeden kısa oturum kaydedilmedi.': 'جلسه‌های کوتاه‌تر از ۳۰ ثانیه ذخیره نمی‌شوند.',
  '30-40 dakika, arada çevirerek yumuşayıp kızarana kadar pişirin.': '۳۰-۴۰ دقیقه بپزید و گاهی برگردانید تا نرم و طلایی شوند.',
