  '300 g tavuk göğsü': '۳۰۰ گرم سینه‌ی مرغ',
  '30–65 yaş arası 5 yılda bir; doktorun daha sık önerebilir.': 'هر ۵ سال بین ۳۰ تا ۶۵ سالگی؛ ممکن است پزشک فواصل کوتاه‌تری توصیه کند.',
