  '35 yaş üstünde 6 ay sonra değerlendirme önerilir.': 'بالای ۳۵ سال، ارزیابی پس از ۶ ماه توصیه می‌شود.',
  '350 g tavuk göğsü': '۳۵۰ گرم سینه‌ی مرغ',
  '36 ürün türü • 6 kategori • Bağımsız seçim rehberi': '۳۶ نوع محصول • ۶ دسته • راهنمای خرید مستقل',
  '37. gebelik haftasından önce gerçekleşen doğumlara erken doğum denir.': 'تولد پیش از هفته‌ی ۳۷ بارداری زایمان زودرس نامیده می‌شود.',
  '37. haftadan önce düzenli kasılma, su gelmesi veya kanama.': 'انقباضات منظم، نشت مایع یا خونریزی پیش از هفته‌ی ۳۷.',
  '37. haftadan önce düzenli kasılmalar (erken doğum).': 'انقباضات منظم پیش از هفته‌ی ۳۷ (زایمان زودرس).',
  '38 °C üstü ateş, ishal veya beslenmeyi reddetme.': 'تب بالای ۳۸ °C، اسهال یا امتناع از شیر.',
  '3–4 yaş: hikâye anlatır, sırasını bekleyebilir, arkadaşlarla birlikte oynamaya başlar. Tek ayak üzerinde kısa süre durur.': '۳–۴ سالگی: قصه می‌گوید، می‌تواند منتظر نوبت بماند، شروع به بازی با دوستان می‌کند. لحظه‌ای روی یک پا می‌ایستد.',
  '3–6 aylık bebekte 39 °C ve üzeri ateş: Aynı gün doktoruna başvur.': 'تب ۳۹ درجه یا بیشتر در نوزاد ۳ تا ۶ ماهه: همان روز به پزشک مراجعه کنید.',
