  '4 ayda başını tutamama, nesneleri gözüyle takip etmeme.': 'نگه نداشتن سر یا دنبال نکردن اشیا با چشم در ۴ ماهگی.',
  '4 dilim somon fileto (her biri yaklaşık 150 g)': '۴ تکه فیله‌ی سالمون (هرکدام حدود ۱۵۰ گرم)',
