  '4 yaş: hikâye anlatma, renkleri tanıma, tek ayak üzerinde durma.': '۴ سالگی: قصه گفتن، شناختن رنگ‌ها، ایستادن روی یک پا.',
  '4 yemek kaşığı ayçiçek yağı (kızartmak için)': '۴ قاشق غذاخوری روغن آفتابگردان (برای سرخ کردن)',
  '4 yemek kaşığı galeta unu': '۴ قاشق غذاخوری پودر سوخاری',
