  '6 ayda hiç ses çıkarmama, vücudun bir tarafını belirgin daha az kullanma.': 'هیچ صدایی درنیاوردن، یا استفاده‌ی آشکارا کمتر از یک سمت بدن در ۶ ماهگی.',
  '6 aydan büyüklerde geniş spektrumlu güneş koruyucu sür, 2 saatte bir yenile.': 'برای کودکان بالای ۶ ماه ضدآفتاب با طیف گسترده بزنید و هر ۲ ساعت تکرار کنید.',
  '6 aydan küçük bebekler doğrudan güneş ışığından uzak tutulmalıdır.': 'نوزادان زیر ۶ ماه باید از نور مستقیم خورشید دور نگه داشته شوند.',
