  '6. ay: yuvarlanma, destekle oturma, adına tepki vermeye başlama.': '۶ ماهگی: غلت زدن، نشستن با تکیه، شروع واکنش به نام خود.',
  '6. hafta: Doğum sonrası kontrol, ruh sağlığı, korunma ve fiziksel iyileşme sorularını doktorunuzla görüşün.': 'هفته ۶: درباره معاینه پس از زایمان، سلامت روان، پیشگیری از بارداری و بهبود جسمی با پزشک صحبت کنید.',
