  '9 ayda desteksiz oturamama veya hiç hece çıkarmama.': 'ننشستن بدون تکیه یا درنیاوردن هیچ هجایی در ۹ ماهگی.',
  '9. ay: desteksiz oturma, emekleme, "ba-ba", "ma-ma" gibi heceler, yabancı kaygısı.': '۹ ماهگی: نشستن بدون تکیه، چهار دست و پا رفتن، هجاهایی مثل «با-با»، «ما-ما»، غریبی کردن.',
