  'AI sunucusu henüz yapılandırılmadı. Bu ekran gerçek AI yanıtı üretmez.': 'سرور هوش مصنوعی هنوز پیکربندی نشده است. این صفحه پاسخ واقعی تولید نمی‌کند.',
  'AI yanıtları hatalı olabilir. Tanı, ilaç, tedavi veya acil sağlık kararları için kullanılmaz. Acil durumda 112’yi arayın.': 'پاسخ‌های هوش مصنوعی ممکن است اشتباه باشند. از آن‌ها برای تشخیص، دارو، درمان یا تصمیم‌های فوری سلامت استفاده نکنید. در شرایط اضطراری با شماره اورژانس محلی تماس بگیرید.',
