  'Adet başlangıç günü': 'روز شروع قاعدگی',
  'Adet başlangıç tarihini seç': 'تاریخ شروع قاعدگی را انتخاب کنید',
  'Adet başlangıç tarihlerini kişisel günlüğüne kaydet. Bu kayıtlar cihazın korumalı yerel depolamasında saklanır; otomatik bulut yedeklemesi yapılmaz. Döngü tahmini, doğurganlık hesabı ya da tıbbi değerlendirme yapılmaz.': 'تاریخ‌های شروع قاعدگی را در دفترچه شخصی خود ذخیره کنید. این ثبت‌ها در حافظه محلی محافظت‌شده دستگاه نگه داشته می‌شوند؛ پشتیبان‌گیری خودکار ابری انجام نمی‌شود. پیش‌بینی چرخه، محاسبه باروری یا ارزیابی پزشکی انجام نمی‌شود.',
  'Adet döneminde bağırsak veya idrar yapmada ağrı.': 'درد هنگام اجابت مزاج یا ادرار در دوران قاعدگی.',
  'Adet dönemindesin. Vücudun yeni bir yumurtlamaya hazırlanıyor.': 'در دوران قاعدگی هستید. بدن برای تخمک‌گذاری جدید آماده می‌شود.',
  'Adet döngünü kaydet; uygulamadaki takvim verimli dönem tahmini verir.': 'چرخه‌تان را ثبت کنید؛ تقویم برنامه تخمینی از دوره‌ی باروری می‌دهد.',
  'Adet döngüsü': 'چرخه‌ی قاعدگی',
  'Adet döngüsü bir adetin ilk gününden bir sonrakinin ilk gününe kadar geçen süredir.': 'چرخه‌ی قاعدگی فاصله‌ی روز اول یک قاعدگی تا روز اول قاعدگی بعدی است.',
  'Adet döngüsü geçmişim': 'سابقه قاعدگی من',
  'Adet gecikmesi, hafif kramp veya az miktarda lekelenme olabilir. Ev gebelik testi pozitif çıkabilir.': 'تأخیر قاعدگی، گرفتگی خفیف یا لکه‌بینی مختصر ممکن است رخ دهد. تست خانگی بارداری ممکن است مثبت شود.',
