  'Anne, bebek ve aile yaşamı için güvenilir başlangıç bilgileri.': 'اطلاعات پایه قابل اعتماد برای زندگی مادر، کودک و خانواده.',
  'Anne, bebek ve kadın yaşamına dair her şey tek yerde.': 'همه‌چیز درباره مادری، نوزادان و زندگی زنان در یک جا.',
  'Annelerin çoğunda ilk 2 hafta ağlama, duygusal dalgalanma görülebilir (doğum sonrası hüzün).': 'بیشتر مادران در ۲ هفته‌ی اول گریه و نوسان خلق دارند (بیبی بلوز).',
