  'Annenden, kayınvalidenden öğrendiğin tarifleri “Tarif ekle” ile yaz. Tarif detaylarındaki “Aile tarif defterime ekle” ile hazır tarifleri de buraya kaydedebilirsin.': 'دستورهایی را که از مادر یا مادرشوهرتان یاد گرفته‌اید با «افزودن دستور پخت» بنویسید. دستورهای آماده را هم می‌توانید از جزئیات دستور با «افزودن به دفتر دستور پخت خانواده من» اینجا ذخیره کنید.',
  'Annenin uykusu': 'خواب مادر',
