  'Aradığınız konuyla ilgili içerikleri cihazınızda bulabilirsiniz. Bu sürüm yapay zekâ sohbeti değil, çevrimdışı anahtar kelime aramasıdır.': 'می‌توانید محتوای موضوع خود را روی دستگاه پیدا کنید. این نسخه جستجوی آفلاین با کلیدواژه است، نه گفتگوی هوش مصنوعی.',
