  'Ateşin derecesinden bağımsız olarak hemen 112’yi ara: nöbet geçirme, morarma, nefes almada zorluk, bardakla bastırınca solmayan döküntü, uyandırılamama ya da aşırı uyku hâli, ense sertliği, bıngıldakta şişlik, 8 saatten uzun süre ıslak bez olmaması.': 'دما هر چه باشد، در این موارد فوراً با شماره اورژانس محلی تماس بگیرید: تشنج، کبودی، دشواری تنفس، بثورات پوستی که با فشار لیوان محو نمی‌شود، بیدار نشدن یا خواب‌آلودگی شدید، سفتی گردن، برآمدگی ملاج، یا بیش از ۸ ساعت بدون پوشک خیس.',
