  'Bebek, gebelik, adet, beslenme, alışveriş ve yaşam araçlarındaki kayıtlar bu cihazdan kalıcı olarak silinecek. Bu işlem geri alınamaz. Önce şifreli yedek alman önerilir.': 'ثبت‌های ابزارهای کودک، بارداری، قاعدگی، تغذیه، خرید و زندگی برای همیشه از این دستگاه حذف می‌شوند. قابل بازگشت نیست. توصیه می‌شود ابتدا پشتیبان رمزگذاری‌شده بگیرید.',
  'Bebek, gebelik, aşı ve tarif soruların · çevrimdışı': 'پرسش‌های شما درباره کودک، بارداری، واکسن و دستور پخت · آفلاین',
  'Bebek, hamilelik, kadın, aile, anılar • Kaydet, takip et, tamamla': 'کودک، بارداری، زنان، خانواده، خاطرات • ذخیره کنید، پیگیری کنید، کامل کنید',
