  'Bebekle konuş, ninni söyle, yüz ifadelerine karşılık ver.': 'با نوزاد صحبت کنید، لالایی بخوانید، به حالت‌های چهره‌اش پاسخ دهید.',
  'Bebekle seyahat': 'سفر با نوزاد',
  'Bebekler her gün yıkanmak zorunda değildir; haftada 2–3 banyo çoğu bebek için yeterlidir.': 'نوزادان نیاز به حمام روزانه ندارند؛ برای بیشترشان ۲–۳ بار در هفته کافی است.',
  'Bebekler mümkün olduğunca uzun süre (en az 15 ay ve üreticinin sınırlarına kadar) arkaya bakan koltukta taşınmalıdır.': 'نوزادان باید تا جای ممکن رو به عقب سفر کنند (دست‌کم ۱۵ ماه و تا محدودیت‌های سازنده).',
  'Bebekler yılda birçok kez soğuk algınlığı geçirebilir; nefes alma şekli en önemli takip noktasıdır.': 'نوزادان ممکن است سالی چند بار سرما بخورند؛ نحوه‌ی تنفس مهم‌ترین چیزی است که باید زیر نظر داشت.',
  'Bebekler, gebeler ve yaşlılar gıda zehirlenmesine daha duyarlıdır.': 'نوزادان، زنان باردار و سالمندان در برابر مسمومیت غذایی آسیب‌پذیرترند.',
  'Bebeklerde ateş': 'تب در نوزادان',
  'Bebeklerde demir desteğini hekim önerisine göre sürdür.': 'مکمل آهن نوزاد را طبق توصیه‌ی پزشک ادامه دهید.',
  'Bebeklerde her yanık, yüz-el-genital bölge yanıkları, avuç içinden büyük yanıklar.': 'هر سوختگی در نوزاد، سوختگی صورت، دست‌ها یا ناحیه‌ی تناسلی، سوختگی بزرگ‌تر از کف دست.',
  'Bebeklerde ishal ve kusmanın en önemli riski sıvı kaybıdır (dehidratasyon).': 'بزرگ‌ترین خطر اسهال و استفراغ در نوزادان از دست دادن مایعات (کم‌آبی) است.',
  'Bebeklerde kabızlık': 'یبوست در نوزادان',
  'Bebeklerde uyku düzeni': 'الگوی خواب نوزادان',
  'Bebeklerimde ara...': 'جستجوی کودکانم...',
  'Bebeklerin yarısından fazlasında görülür; çoğu 12. aya kadar kendiliğinden geçer.': 'در بیش از نیمی از نوزادان رخ می‌دهد؛ بیشترشان تا ۱۲ ماهگی از آن رها می‌شوند.',
  'Bebekli ev düzeni ve zaman yönetimi': 'سازمان‌دهی خانه و مدیریت زمان با نوزاد',
  'Bebekli yaşamın ilk yılı yeni harcamalar getirir; planlamak stresi azaltır.': 'سال اول با نوزاد هزینه‌های تازه‌ای می‌آورد؛ برنامه‌ریزی استرس را کم می‌کند.',
  'Bebekte her beslenme sonrası belirgin rahatsızlık, kanlı dışkı veya döküntü varsa (nadiren besin alerjisi).': 'اگر نوزاد پس از هر شیردهی ناراحتی آشکار، مدفوع خونی یا بثورات دارد (به‌ندرت حساسیت غذایی).',
  'Bebeğe bakamama veya bağ kuramama hissi.': 'احساس ناتوانی در مراقبت یا ایجاد پیوند با نوزاد.',
  'Bebeğe bakımda yaşına uygun küçük görevler ver.': 'در مراقبت از نوزاد کارهای کوچک مناسب سن به او بسپارید.',
  'Bebeği asla sarsma: sarsılmış bebek sendromu kalıcı beyin hasarına yol açabilir.': 'هرگز نوزاد را تکان ندهید: سندرم تکان دادن نوزاد می‌تواند آسیب مغزی دائمی ایجاد کند.',
  'Bebeği biberonla uyutma; şekerli içecek verme.': 'نوزاد را با شیشه شیر نخوابانید؛ نوشیدنی شیرین ندهید.',
  'Bebeği değiştirme masası, yatak veya kanepe üzerinde bir an bile yalnız bırakmamak düşmeleri önler.': 'هرگز نوزاد را حتی لحظه‌ای روی میز تعویض، تخت یا مبل تنها نگذارید؛ این از افتادن جلوگیری می‌کند.',
  'Bebeği gün ışığında doğrudan güneşe çıkarmak tedavi yerine geçmez.': 'گذاشتن نوزاد زیر نور مستقیم خورشید جایگزین درمان نیست.',
  'Bebeği her uykuda başının farklı tarafına bakacak şekilde yatır (yine sırtüstü).': 'در هر خواب جهت سر نوزاد را عوض کنید (باز هم به پشت).',
  'Bebeği ince giydir, odayı serin tut, sık sık emzir veya sıvı ver.': 'لباس سبک بپوشانید، اتاق را خنک نگه دارید و مرتب شیر یا مایعات بدهید.',
  'Bebeği memeden ayırırken parmağınla vakumu kes.': 'هنگام جدا کردن نوزاد از پستان، مکش را با انگشت بشکنید.',
  'Bebeği suda asla yalnız bırakmayın.': 'هرگز نوزاد را در آب تنها نگذارید.',
  'Bebeği sırtüstü, düz ve sert bir uyku yüzeyine yatırın; uyku alanında gevşek yastık ve örtü bulundurmayın.': 'نوزاد را به پشت روی سطح خواب صاف و سفت بخوابانید؛ بالش و روانداز شل را از فضای خواب دور نگه دارید.',
  'Bebeği uykulu ama uyanıkken yatağa koymayı dene.': 'سعی کنید نوزاد را خواب‌آلود اما بیدار در تخت بگذارید.',
  'Bebeği yüksek yüzeylerde bir an bile yalnız bırakma; sarsma. Arkaya bakan oto koltuğu kullan. 3 aydan küçük bebekte ateş acil değerlendirme gerektirir.': 'هرگز نوزاد را حتی لحظه‌ای روی سطح بلند تنها نگذارید؛ تکان ندهید. از صندلی ماشین رو به عقب استفاده کنید. تب در نوزاد زیر ۳ ماه نیاز به ارزیابی فوری دارد.',
