  'Bebeğin içtiği sütün artanı 2 saat içinde kullanılmalı ya da dökülmelidir.': 'شیری که پس از نوشیدن نوزاد باقی می‌ماند باید ظرف ۲ ساعت مصرف یا دور ریخته شود.',
  'Bebeğin kendi hareketini başlatmasına fırsat verin; destek olmadan ayakta durmaya zorlamayın.': 'بگذارید نوزاد حرکاتش را خودش شروع کند؛ او را مجبور به ایستادن بدون تکیه نکنید.',
