  'Bez, cilt ve beslenme kayıtlarını izleyin. Kontrolleri sağlık ekibinizle planlayın; ateş veya beslenme güçlüğünde yaşa uygun acil değerlendirme gereksinimini sorun.': 'ثبت‌های پوشک، پوست و تغذیه را پیگیری کنید. معاینات را با تیم سلامت برنامه‌ریزی کنید؛ درباره‌ی فوریت تب یا مشکلات تغذیه بر اساس سن بپرسید.',
