  'Biberon ve mama ile takviye, emzirme sıklığını azaltarak süt üretimini düşürebilir.': 'تکمیل با شیشه و شیر خشک می‌تواند با کم کردن دفعات شیردهی تولید شیر را کاهش دهد.',
