  'Biberonla beslerken emziği tamamen sütle dolu tutacak açı ver.': 'هنگام تغذیه با شیشه، آن را طوری کج کنید که سرشیشه پر از شیر بماند.',
  'Biberonla uykuya dalma ve şekerli içecekler diş sağlığını olumsuz etkileyebilir.': 'خوابیدن با شیشه و نوشیدنی‌های شیرین ممکن است به سلامت دندان آسیب بزند.',
  'Biberonla uyuma ve sık şekerli atıştırmalık çürük riskini artırır.': 'خوابیدن با شیشه و میان‌وعده‌های شیرین مکرر خطر پوسیدگی را افزایش می‌دهند.',
  'Biberonu yatarak vermek kulak iltihabı riskini artırabilir.': 'شیشه دادن در حالت درازکش می‌تواند خطر عفونت گوش را افزایش دهد.',
