  'Bir profile dokunarak beslenme, uyku, büyüme ve sağlık kayıtlarını açabilirsiniz.': 'روی یک نمایه بزنید تا ثبت‌های تغذیه، خواب، رشد و سلامت باز شود.',
  'Bir renk seçip hikâyedeki o renkte nesneleri bulun.': 'رنگی انتخاب کنید و در قصه اشیای آن رنگ را پیدا کنید.',
  'Bir ruh sağlığı uzmanıyla konuşmayı düşün.': 'صحبت با متخصص سلامت روان را در نظر بگیرید.',
  'Bir sese dokun; tekrar dokununca durur. Bir gürültü ile bir ninniyi aynı anda çalabilirsin. Sesler telefonda üretilir, internet gerekmez.': 'روی یک صدا بزنید؛ برای توقف دوباره بزنید. می‌توانید یک نویز و یک لالایی را هم‌زمان پخش کنید. صداها روی گوشی تولید می‌شوند؛ به اینترنت نیاز نیست.',
