  'Bir yıl düzenli korunmasız ilişkiye rağmen gebelik olmaması infertilite olarak değerlendirilir.': 'باردار نشدن پس از یک سال رابطه‌ی منظم بدون پیشگیری ناباروری محسوب می‌شود.',
