  'Birincil adet sancısı genellikle adetin ilk 1–2 gününde görülür.': 'درد قاعدگی اولیه معمولاً در ۱–۲ روز اول قاعدگی احساس می‌شود.',
  'Birkaç adım yürür; nesneleri üst üste koymayı dener. Tanıdık kişileri isimle tanır.': 'چند قدم راه می‌رود؛ سعی می‌کند اشیا را روی هم بچیند. افراد آشنا را با نام می‌شناسد.',
