  'Bitkisel çaylar ve takviyeler "doğal" olsa da güvenli olmayabilir.': 'دمنوش‌ها و مکمل‌های گیاهی حتی اگر «طبیعی» باشند ممکن است ایمن نباشند.',
  'Blenderdan geçirip ince kıyılmış dereotunu ekleyin.': 'با مخلوط‌کن یکدست کنید و شوید ریزخردشده را اضافه کنید.',
  'Blenderdan geçirip kıvamını sıcak suyla ayarlayın.': 'با مخلوط‌کن یکدست کنید و غلظت را با آب داغ تنظیم کنید.',
  'Blenderdan geçirmeden önce çorbayı birkaç dakika ılıtın; sıcak buhar kapağı itebilir.': 'پیش از مخلوط کردن بگذارید سوپ چند دقیقه خنک شود؛ بخار داغ ممکن است در را پرت کند.',
