  'Boyun ayarı': 'تنظیم دور گردن',
  'Boyun kaslarındaki gerginlik (tortikolis) bebeğin hep aynı tarafa bakmasına neden olabilir.': 'سفتی عضلات گردن (تورتیکولی) می‌تواند باعث شود نوزاد همیشه به یک سمت نگاه کند.',
  'Boyun çevresinde güvenli uyuma dikkat edin.': 'مطمئن شوید به‌طور ایمن دور گردن بسته می‌شود.',
