  'Boyut uyumu': 'تناسب اندازه',
  'Boğulma (yabancı cisim) ilk yardımı': 'کمک‌های اولیه در خفگی (جسم خارجی)',
  'Boğulma sessiz ve çok hızlı gerçekleşir; küçük çocuklar birkaç santimetre suda bile boğulabilir.': 'غرق شدن بی‌صدا و بسیار سریع است؛ کودکان خردسال در چند سانتی‌متر آب هم ممکن است غرق شوند.',
  'Boğulma tehlikesi sonrası öksürük, nefes darlığı veya halsizlik.': 'سرفه، تنگی نفس یا ضعف پس از نزدیک به غرق شدن.',
