  'Bugünün önerileri ✨': 'پیشنهادهای امروز ✨',
  'Buharda iyice yumuşatın.': 'بخارپز کنید تا خیلی نرم شود.',
  'Buharda tamamen yumuşayana kadar pişirin.': 'بخارپز کنید تا کاملاً نرم شود.',
  'Bulantı azalmaya başlayabilir; ani kalkınca baş dönmesi olabilir.': 'تهوع ممکن است کمتر شود؛ هنگام سریع بلند شدن ممکن است سرگیجه داشته باشید.',
  'Bulantı başlayabilir; kokulara hassasiyet artabilir.': 'تهوع ممکن است شروع شود؛ حساسیت به بوها ممکن است بیشتر شود.',
  'Bulantı bu haftalarda en yoğun olabilir.': 'تهوع ممکن است در این هفته‌ها در اوج باشد.',
  'Bulantı için aç kalmamaya çalış; hiçbir şey tutamıyorsan doktoruna başvur.': 'برای تهوع سعی کنید گرسنه نمانید؛ اگر چیزی نگه نمی‌دارید، به پزشک مراجعه کنید.',
  'Bulantı ve kusma gebelerin çoğunda görülür ve çoğunlukla 12–16. haftalarda azalır.': 'تهوع و استفراغ بیشتر زنان باردار را درگیر می‌کند و معمولاً بین هفته‌های ۱۲ تا ۱۶ کم می‌شود.',
  'Bulantı, duygu dalgalanmaları ve yorgunluk sık görülür.': 'تهوع، نوسان خلق و خستگی شایع‌اند.',
  'Bulaşık deterjanı': 'مایع ظرفشویی',
  'Bulgur pilavı': 'پلو بلغور',
