  'Domatesi ekleyip orta ateşte 8 dakika, sos koyulaşana kadar pişirin; tuzu ayarlayın.': 'گوجه را اضافه کنید و روی حرارت متوسط ۸ دقیقه بپزید تا سس غلیظ شود؛ نمکش را تنظیم کنید.',
  'Domatesi ince dilimleyin.': 'گوجه را نازک ورقه کنید.',
  'Domatesi ve suyu ekleyip 10 dakika kaynatın.': 'گوجه و آب را اضافه کنید و ۱۰ دقیقه بجوشانید.',
  'Domatesleri ekleyip diğer dilimle kapatın.': 'گوجه‌ها را بگذارید و با برش دیگر بپوشانید.',
  'Domatesleri rendeleyin, soğanı ince doğrayın.': 'گوجه‌ها را رنده و پیاز را ریز خرد کنید.',
  'Domatesleri ve patlıcanları ekleyip suyu ilave edin.': 'گوجه و بادمجان را اضافه کنید و آب را بریزید.',
