  'Doz ve kullanım süresini doktorunun ya da eczacının önerisine göre gir. Uygulama doz önermez. Gebelikte ve emzirirken her yeni ilaç için doktoruna danış.': 'دوز و مدت را طبق توصیه پزشک یا داروساز وارد کنید. برنامه دوز توصیه نمی‌کند. در بارداری و شیردهی درباره هر داروی تازه از پزشک بپرسید.',
