  'Doğranmış patates, patlıcan, kabak ve domatesi ekleyin.': 'سیب‌زمینی، بادمجان، کدو و گوجه‌ی خردشده را اضافه کنید.',
  'Doğranmış sebzeleri yağda 5 dakika soteleyin.': 'سبزیجات خردشده را ۵ دقیقه در روغن تفت دهید.',
  'Doğranmış soğan ve havucu yağda soteleyin.': 'پیاز و هویج خردشده را در روغن تفت دهید.',
  'Doğranmış soğanı yağda yumuşatıp salçayı kavurun.': 'پیاز خردشده را در روغن نرم کنید و رب را تفت دهید.',
  'Doğru kavramada bebeğin ağzı geniş açık, dudakları dışa dönük ve meme başının çevresindeki koyu alanın büyük kısmı ağzındadır.': 'در گرفتن درست پستان، دهان نوزاد کاملاً باز، لب‌ها رو به بیرون و بیشتر هاله‌ی تیره‌ی اطراف نوک پستان در دهان است.',
  'Doğru takılmış ve yaşa uygun oto koltuğu trafik kazalarında ölüm ve ağır yaralanma riskini büyük ölçüde azaltır.': 'صندلی ماشین مناسب سن و درست نصب‌شده خطر مرگ و آسیب جدی در تصادفات را بسیار کاهش می‌دهد.',
  'Doğru temizlik, ayırma, pişirme ve soğutma gıda kaynaklı hastalıkları önler.': 'تمیز کردن، جدا کردن، پختن و سرد کردن درست از بیماری‌های ناشی از غذا پیشگیری می‌کند.',
  'Doğru yolda Harun': 'هارون راه‌یافته',
