  'Doğum Sonrası & Annelik': 'پس از زایمان و مادری',
  'Doğum ağrısıyla baş etmek için ilaçsız ve ilaçlı birçok yöntem vardır.': 'روش‌های دارویی و غیردارویی بسیاری برای کنار آمدن با درد زایمان وجود دارد.',
  'Doğum başlamazsa doktorunun izlem planını öğren; genellikle 41. haftada değerlendirme yapılır.': 'اگر زایمان شروع نشد، برنامه‌ی پایش پزشک را بپرسید؛ معمولاً در هفته‌ی ۴۱ ارزیابی انجام می‌شود.',
  'Doğum başlangıcı belirtileri': 'نشانه‌های شروع زایمان',
  'Doğum bekleniyor': 'زایمان مورد انتظار',
  'Doğum belirtilerini ve ne zaman hastaneye gideceğini gözden geçir.': 'نشانه‌های زایمان و زمان رفتن به بیمارستان را مرور کنید.',
  'Doğum günleri': 'تولدها',
  'Doğum hazırlık eğitimleri bilinmezliği azaltabilir.': 'کلاس‌های آمادگی زایمان می‌توانند عدم قطعیت را کم کنند.',
  'Doğum hazırlık eğitimleri nefes ve gevşeme tekniklerini öğrenmeye yardımcı olur.': 'کلاس‌های آمادگی زایمان به یادگیری فنون تنفس و آرام‌سازی کمک می‌کنند.',
  'Doğum hazırlık sınıflarına katılmayı düşün.': 'شرکت در کلاس‌های آمادگی زایمان را در نظر بگیرید.',
  'Doğum hazırlık sınıflarını araştır.': 'درباره‌ی کلاس‌های آمادگی زایمان تحقیق کنید.',
  'Doğum izni ve çalışan anne hakları': 'مرخصی زایمان و حقوق مادران شاغل',
  'Doğum kasılmalarının süresi ve aralığı': 'مدت و دفعات انقباض‌های زایمان',
  'Doğum planı': 'برنامه زایمان',
  'Doğum planı esnek olmalıdır; tıbbi durum değişebilir.': 'برنامه‌ی زایمان باید انعطاف‌پذیر باشد؛ وضعیت پزشکی ممکن است تغییر کند.',
  'Doğum planı ve hazırlık': 'برنامه و آمادگی زایمان',
  'Doğum planı, doğumla ilgili tercihlerini ekiple paylaşmanı kolaylaştıran kısa bir nottur.': 'برنامه‌ی زایمان یادداشتی کوتاه است که به شما کمک می‌کند ترجیحاتتان را با تیم در میان بگذارید.',
  'Doğum referansı eksik': 'مرجع تولد موجود نیست',
  'Doğum sonrası': 'پس از زایمان',
  'Doğum sonrası bakım': 'مراقبت پس از زایمان',
  'Doğum sonrası bakım ekranları': 'صفحه‌های مراقبت پس از زایمان',
  'Doğum sonrası depresyon her 7–10 anneden birinde görülür ve tedavi edilebilir.': 'افسردگی پس از زایمان از هر ۷–۱۰ مادر یک نفر را درگیر می‌کند و قابل درمان است.',
  'Doğum sonrası destek': 'حمایت پس از زایمان',
  'Doğum sonrası dikişler genellikle birkaç haftada iyileşir; temizlik ve dinlenme iyileşmeyi destekler.': 'بخیه‌های پس از زایمان معمولاً ظرف چند هفته خوب می‌شوند؛ بهداشت و استراحت به بهبود کمک می‌کند.',
  'Doğum sonrası doğum kontrolü': 'پیشگیری از بارداری پس از زایمان',
  'Doğum sonrası duygusal dalgalanmalar görülebilir. Yoğun üzüntü, kaygı veya işlev kaybı sürüyorsa profesyonel destek alın. Kendinize veya bebeğe zarar verme düşüncesinde acil yardım isteyin.': 'نوسانات عاطفی پس از زایمان رایج است. اگر غم شدید، اضطراب یا دشواری در انجام کارها ادامه یافت، حمایت تخصصی بگیرید. اگر فکر آسیب زدن به خود یا کودک دارید، کمک فوری بخواهید.',
  'Doğum sonrası günlük': 'دفترچه پس از زایمان',
  'Doğum sonrası hüzün ve depresyon': 'افسردگی خفیف پس از زایمان و افسردگی پس از زایمان',
  'Doğum sonrası idrar kaçırma yaygındır ve çoğu zaman tedavi edilebilir.': 'نشت ادرار پس از زایمان شایع است و اغلب قابل درمان است.',
  'Doğum sonrası ilk saat: ten tene temas': 'ساعت اول پس از تولد: تماس پوست با پوست',
  'Doğum sonrası kontrol genellikle 6. haftada yapılır; daha erken kontroller de önerilebilir.': 'معاینه‌ی پس از زایمان معمولاً در ۶ هفتگی است؛ معاینات زودتر هم ممکن است توصیه شود.',
  'Doğum sonrası kontrol randevumu planladım': 'معاینه پس از زایمانم را برنامه‌ریزی کرده‌ام',
  'Doğum sonrası kontrolde yöntem seçeneklerini hekiminle konuş.': 'گزینه‌ها را در معاینه‌ی پس از زایمان با پزشک بررسی کنید.',
  'Doğum sonrası kontrolleri sağlık ekibinizle planlayın. Kanama, ağrı, ilaçlar, korunma ve emzirme ile ilgili sorularınızı not edin.': 'معاینات پس از زایمان را با تیم درمان برنامه‌ریزی کنید. پرسش‌هایتان درباره خونریزی، درد، دارو، پیشگیری از بارداری و شیردهی را بنویسید.',
  'Doğum sonrası korse': 'شکم‌بند پس از زایمان',
  'Doğum sonrası ve annelik': 'پس از زایمان و مادری',
  'Doğum sonrası yaklaşık {0}. gün • {1}. hafta': 'حدود روز {0} پس از زایمان • هفته {1}',
  'Doğum sırasında ihtiyaçlarını ekibe açıkça söyle.': 'در حین زایمان نیازهایتان را به‌روشنی به تیم بگویید.',
  'Doğum tarihi': 'تاریخ تولد',
  'Doğum tarihi eklenmedi': 'تاریخ تولد افزوده نشده',
  'Doğum tarihi gelecekte olamaz.': 'تاریخ تولد نمی‌تواند در آینده باشد.',
  'Doğum tarihi girildiğinde bebeğin ayına göre açılır': 'با ورود تاریخ تولد، متناسب با سن کودک باز می‌شود',
  'Doğum tarihi girilmedi: tüm yaş grupları gösteriliyor.': 'تاریخ تولد وارد نشده: همه گروه‌های سنی نمایش داده می‌شوند.',
  'Doğum tarihi seç': 'انتخاب تاریخ تولد',
  'Doğum tarihi seçilmelidir.': 'باید تاریخ تولد انتخاب شود.',
