  'Doğum tarihim (yaşa uygun kontroller için)': 'تاریخ تولد من (برای معاینات متناسب با سن)',
  'Doğum tarihim: {0}': 'تاریخ تولد من: {0}',
  'Doğum tarihinden önceki kayıt': 'ثبت پیش از تاریخ تولد',
