  'Doğum tarihini seç': 'تاریخ تولد را انتخاب کنید',
  'Doğum tarihini “Anne profilim”e girersen yaşına uygun kontroller gösterilir.': 'اگر تاریخ تولد خود را در «نمایه من» وارد کنید، معاینات متناسب با سنتان نمایش داده می‌شود.',
  'Doğum tercihlerini (doğum planı) yazmaya başla.': 'نوشتن ترجیحات زایمانتان (برنامه‌ی زایمان) را شروع کنید.',
  'Doğum tercihlerini ve sorularını önceden hekiminle konuş.': 'ترجیحات و سؤال‌هایتان درباره‌ی زایمان را از قبل با پزشک در میان بگذارید.',
  'Doğum yapacağın hastanenin acil iletişim bilgilerini telefonuna kaydet.': 'اطلاعات تماس اورژانس بیمارستانی را که در آن زایمان می‌کنید در گوشی ذخیره کنید.',
  'Doğum yapacağın hastaneyi ve ulaşımı netleştir.': 'بیمارستان زایمان و راه رسیدن به آن را قطعی کنید.',
  'Doğum yeri, ulaşım ve destek kişini planla.': 'محل زایمان، رفت‌وآمد و همراه حمایتگر را برنامه‌ریزی کنید.',
  'Doğum çantasını hazırla': 'ساک بیمارستان را آماده کنید',
  'Doğum şekli anne ve bebeğin durumuna göre hekimle birlikte planlanır.': 'نحوه‌ی زایمان با پزشک و بر اساس وضعیت شما و نوزاد برنامه‌ریزی می‌شود.',
  'Doğum şekline göre iyileşme farklılık gösterir. Ağrı, kanama, yara bakımı ve hareket konusunda taburculuk önerilerini takip edin. Dinlenme için yakınlarınızdan destek isteyin.': 'بهبودی بسته به نوع زایمان متفاوت است. توصیه‌های ترخیص درباره درد، خونریزی، مراقبت از زخم و تحرک را دنبال کنید. از عزیزانتان کمک بخواهید تا بتوانید استراحت کنید.',
  'Doğum, nüfus müdürlüğüne yasal süre içinde bildirilmelidir; hastanelerde çoğu zaman doğum bildirimi elektronik yapılır.': 'تولد باید در مهلت قانونی ثبت شود؛ بیمارستان‌ها اغلب تولد را الکترونیکی اعلام می‌کنند.',
  'Doğum: {0}': 'تولد: {0}',
  'Doğum: {0}.{1}.{2}': 'تولد: {0}.{1}.{2}',
  'Doğuma hazırlık listesi': 'فهرست آمادگی زایمان',
  'Doğuma yakın dönem: doğum belirtileri ve başvuru planını sağlık ekibinle netleştir.': 'نزدیک موعد: نشانه‌های زایمان و زمان رفتن به بیمارستان را با تیم درمان روشن کنید.',
  'Doğumda ağrı yönetimi': 'تسکین درد زایمان',
  'Doğumdan aylar sonra süren idrar veya gaz kaçırma.': 'نشت ادرار یا گاز که ماه‌ها پس از زایمان ادامه دارد.',
  'Doğumdan hemen sonra ten tene temas ve ilk saatte emzirme anne ve bebeğe birçok fayda sağlar.': 'تماس پوست با پوست بلافاصله پس از تولد و شیردهی در ساعت اول مزایای بسیاری برای مادر و نوزاد دارد.',
  'Doğumdan sonra işe dönüş hem duygusal hem pratik bir geçiştir; önceden planlamak kolaylaştırır.': 'بازگشت به کار پس از زایمان گذاری هم عاطفی و هم عملی است؛ برنامه‌ریزی از قبل کمک می‌کند.',
  'Doğumdan sonra nüfus kaydı ve sağlık güvencesi işlemlerinin zamanında yapılması gerekir.': 'پس از تولد، ثبت احوال و پوشش بیمه‌ی سلامت باید به‌موقع انجام شود.',
  'Doğumdan sonraki ilk 6 hafta vücudun toparlandığı, dinlenme ve desteğin en çok gerektiği dönemdir.': '۶ هفته‌ی اول پس از زایمان زمانی است که بدن بهبود می‌یابد و بیشترین نیاز به استراحت و حمایت را دارید.',
  'Doğumdan sonraki ilk adet gelmeden de gebelik oluşabilir.': 'حتی پیش از اولین قاعدگی پس از زایمان ممکن است باردار شوید.',
  'Doğumdan sonraki ilk günlerde hüzün yaygındır; iki haftadan uzun süren belirtiler depresyon olabilir.': 'احساس غم در روزهای اول پس از زایمان شایع است؛ علائمی که بیش از دو هفته طول بکشد ممکن است افسردگی باشد.',
  'Doğumdan sonraki ilk günlerde topuk kanı ve işitme taraması yapılır; 3–5. günde ilk kontrol önerilir.': 'در روزهای اول پس از تولد غربالگری خون پاشنه و شنوایی انجام می‌شود؛ اولین معاینه در روز ۳–۵ توصیه می‌شود.',
  'Doğumdan sonraki ilk hafta içinde topuk kanı taraması ve işitme taraması yapılır.': 'غربالگری خون پاشنه و غربالگری شنوایی در هفته‌ی اول پس از تولد انجام می‌شود.',
  'Doğumdan sonraki ilk kontrolü (genellikle 3–5. gün) aksatma.': 'اولین معاینه پس از تولد (معمولاً روز ۳–۵) را از دست ندهید.',
  'Doğumdan sonraki kontrolleri aksatma.': 'معاینات پس از تولد را از دست ندهید.',
  'Doğu’nun hanı': 'خان شرق',
