  'Dudak veya yüzde morarma, nefes durmaları: 112.': 'کبودی لب یا صورت، وقفه‌ی تنفس: با شماره‌ی اورژانس محلی تماس بگیرید.',
  'Dudak/dil şişmesi, nefes darlığı, hırıltı, yaygın kurdeşen, bilinç değişikliği: 112.': 'تورم لب/زبان، تنگی نفس، خس‌خس، کهیر گسترده، تغییر هوشیاری: با شماره‌ی اورژانس محلی تماس بگیرید.',
  'Duman dedektörü': 'آشکارساز دود',
