  'Durum sunucudan doğrulandı.': 'وضعیت با سرور تأیید شد.',
  'Duvara düşen gölgeleri birlikte inceleyin.': 'با هم به سایه‌های روی دیوار نگاه کنید.',
  'Duygu aynası': 'آینه‌ی احساسات',
