  'Duyguları adlandırma': 'نام بردن احساسات',
  'Duyguları adlandırma ("kızgın mısın?"), rol oyunları, açık havada tırmanma (alçak ve güvenli).': 'نام بردن احساسات («عصبانی هستی؟»)، بازی نقش، بالا رفتن در بیرون (کم‌ارتفاع و ایمن).',
  'Duyguları adlandırmasına yardım et ("kızgın görünüyorsun").': 'کمک کنید احساساتش را نام ببرد («به نظر عصبانی هستی»).',
  'Duygularını güvendiğin biriyle paylaş; yardım istemek güçlü bir adımdır.': 'احساساتتان را با فردی مورد اعتماد در میان بگذارید؛ کمک خواستن گامی قوی است.',
  'Duygularını paylaşabileceğin kişilerle konuş.': 'با کسانی صحبت کنید که می‌توانید احساساتتان را با آن‌ها در میان بگذارید.',
  'Duyu': 'حواس',
  'Duyular gelişir; dokunmayı hissedebilir, kaşları belirir.': 'حواس رشد می‌کنند؛ نوزاد می‌تواند لمس را احساس کند و ابروها ظاهر می‌شوند.',
  'Duyusal algı gelişir; hızla kilo alır.': 'درک حسی رشد می‌کند؛ نوزاد به‌سرعت وزن می‌گیرد.',
  'Döküntü, dudak/dil şişmesi, kusma veya nefes darlığı: alerji, acil olabilir.': 'بثورات، تورم لب/زبان، استفراغ یا تنگی نفس: حساسیت، ممکن است اورژانسی باشد.',
  'Döllenmiş yumurta (zigot) hızla bölünerek rahme doğru ilerler.': 'تخمک لقاح‌یافته (زیگوت) در مسیر رحم به‌سرعت تقسیم می‌شود.',
  'Döngü Takibi': 'پیگیری چرخه',
  'Döngü değişimi, cilt ve diğer belirtileri hekiminizle görüşmek için not edin.': 'تغییرات چرخه، پوست و دیگر علائم را برای گفتگو با پزشک یادداشت کنید.',
  'Döngü kayıtları': 'ثبت‌های چرخه',
  'Döngü süresi: ortalama {0} gün ({1} kayıttan)': 'طول چرخه: میانگین {0} روز (از {1} ثبت)',
  'Döngü süresi: {0} gün (varsayılan; daha fazla kayıt girince ölçülür)': 'طول چرخه: {0} روز (پیش‌فرض؛ با ثبت‌های بیشتر اندازه‌گیری می‌شود)',
  'Döngü uzunluğu (gün)': 'طول چرخه (روز)',
  'Döngü ve belirtiler': 'چرخه و علائم',
  'Döngü • Sağlık': 'چرخه • سلامت',
  'Döngü, gebelik, doğum sonrası ve belirtiler': 'چرخه، بارداری، پس از زایمان و علائم',
  'Döngü, gebelik, doğum sonrası ve kontrol notları': 'چرخه، بارداری، پس از زایمان و یادداشت‌های معاینه',
  'Döngü, gebelik, doğum sonrası ve menopoz notları': 'چرخه، بارداری، پس از زایمان و یادداشت‌های یائسگی',
  'Döngünün sürekli 21 günden kısa veya 35 günden uzun olması.': 'چرخه‌هایی که مدام کوتاه‌تر از ۲۱ روز یا بلندتر از ۳۵ روز هستند.',
  'Dönüşten 2–3 hafta önce bakım düzenini denemeye başla.': '۲–۳ هفته پیش از بازگشت، آزمودن ترتیب مراقبت را شروع کنید.',
  'Dördüncü; ilkbahar': 'چهارم؛ بهار',
  'Dün, ': 'دیروز، ',
  'Dünya': 'جهان',
  'Dünya mutfağı': 'آشپزی جهانی',
  'Dünyaya önem vermeyen, sofu': 'زاهد، بی‌اعتنا به دنیا',
  'Dünyayı fetheden': 'جهانگشا',
  'Dürüst han': 'خان درستکار',
  'Düzenle': 'ویرایش',
  'Düzenleyen; şair': 'نظم‌دهنده؛ شاعر',
  'Düzenli ana ve ara öğün fırsatları sunun; açlık-tokluk işaretlerine saygı gösterin. Üzüm, sert kuruyemiş ve benzeri boğulma risklerini uygun şekilde hazırlayın.': 'وعده‌ها و میان‌وعده‌های منظم بدهید؛ به نشانه‌های گرسنگی و سیری احترام بگذارید. انگور، مغزهای سفت و موارد مشابه پرخطر از نظر خفگی را به‌درستی آماده کنید.',
  'Düzenli egzersiz ve dengeli beslenme belirtileri azaltabilir.': 'ورزش منظم و رژیم متعادل می‌تواند علائم را کم کند.',
  'Düzenli egzersiz, kalsiyum ve D vitamini açısından zengin beslenme.': 'ورزش منظم و رژیم غنی از کلسیم و ویتامین D.',
  'Düzenli egzersiz, yeterli uyku, tuz ve kafeini azaltmak yardımcı olabilir.': 'ورزش منظم، خواب کافی و کاهش نمک و کافئین می‌تواند کمک کند.',
  'Düzenli harcamaları ve yaklaşan ihtiyaçları yazın. Alışveriş öncesinde evdeki stokları kontrol edin.': 'هزینه‌های منظم و نیازهای پیش‌رو را بنویسید. پیش از خرید موجودی خانه را بررسی کنید.',
  'Düzenli hareket, uyku ve dengeli beslenme duygudurumu destekler.': 'تحرک منظم، خواب و رژیم متعادل از خلق شما حمایت می‌کنند.',
  'Düzenli kontrol et; çatlak veya yıpranmışsa değiştir.': 'مرتب بررسی کنید؛ اگر ترک خورده یا فرسوده است عوضش کنید.',
  'Düzenli kontrol planı': 'برنامه‌ی معاینات منظم',
  'Düzenli kullandığım ilaçlar': 'داروهایی که به‌طور منظم مصرف می‌کنم',
  'Düzenli uyku ve uyanma saatlerini not edin; çocuğun ihtiyaçlarına göre rutini uyarlayın.': 'ساعت‌های منظم خواب و بیداری را یادداشت کنید؛ روال را با نیازهای کودک تطبیق دهید.',
  'Düzenli ve giderek sıklaşan kasılmalar, su gelmesi ve nişan gelmesi doğumun başladığını gösterebilir.': 'انقباضات منظمی که به هم نزدیک‌تر می‌شوند، پاره شدن کیسه‌ی آب و دفع ترشح خونی می‌توانند نشانه‌ی شروع زایمان باشند.',
  'Düzenli yürüyüş gibi bir egzersiz rutini oluştur.': 'روال ورزشی مثل پیاده‌روی منظم بسازید.',
  'Düzenli, hafif-orta egzersiz (yürüyüş, yüzme, gebe yogası) faydalıdır.': 'ورزش منظم سبک تا متوسط (پیاده‌روی، شنا، یوگای بارداری) مفید است.',
  'Düzensiz adet, androjen fazlalığı belirtileri ve yumurtalıklarda çok sayıda küçük folikülle seyreden yaygın bir hormonal durumdur.': 'یک وضعیت هورمونی شایع با قاعدگی نامنظم، نشانه‌های افزایش آندروژن و فولیکول‌های کوچک متعدد در تخمدان‌ها.',
  'Düzensiz adet, kronik hastalık veya önceki gebelik kayıpları varsa erkenden.': 'زودتر، اگر قاعدگی نامنظم، بیماری مزمن یا سابقه‌ی سقط دارید.',
  'Düzensiz ve düzenli kasılmaları ayırt etmeye çalış.': 'سعی کنید انقباضات نامنظم و منظم را از هم تشخیص دهید.',
  'Düzensiz veya hiç adet görmeme, bilinen tüp veya rahim sorunu.': 'قاعدگی نامنظم یا نبود آن، مشکل شناخته‌شده‌ی لوله یا رحم.',
  'Düzensiz veya seyrek adet, sivilce, tüylenme ve kilo artışı görülebilir.': 'قاعدگی نامنظم یا کم‌تکرار، آکنه، موی زائد و افزایش وزن ممکن است رخ دهد.',
  'Düzleşme 4 aydan sonra artıyorsa veya alın/kulaklarda asimetri varsa.': 'اگر صافی پس از ۴ ماهگی بیشتر شود یا پیشانی/گوش‌ها نامتقارن باشند.',
  'Düğme pil veya mıknatıs yutma şüphesi: hemen acil servis.': 'شک به بلعیدن باتری سکه‌ای یا آهنربا: فوراً به اورژانس بروید.',
  'Düğme pilleri ve mıknatısları çocuklardan uzak tut.': 'باتری‌های سکه‌ای و آهنرباها را از کودکان دور نگه دارید.',
  'Düş': 'رؤیا',
  'Düşme sonrası diş kırığı veya yerinden çıkma: hemen diş hekimi.': 'دندان شکسته یا افتاده پس از زمین خوردن: فوراً به دندانپزشک مراجعه کنید.',
  'Düşme ve darbe riski olan sporlar ile sırtüstü uzun süre yatmayı gerektiren hareketler önerilmez.': 'ورزش‌های با خطر افتادن یا ضربه و حرکاتی که نیاز به درازکشیدن طولانی به پشت دارند توصیه نمی‌شوند.',
  'Düşme ve kafa travması': 'افتادن و آسیب سر',
  'Düşmeler, zehirlenmeler, yanıklar ve boğulma en sık ev kazalarıdır.': 'افتادن، مسمومیت، سوختگی و غرق شدن شایع‌ترین حوادث خانگی‌اند.',
  'Düştükten sonra birkaç gün az miktarda kanlı lekelenme olabilir.': 'لکه‌بینی خونی مختصر تا چند روز پس از افتادن ممکن است.',
  'Düşük ışıklı gece aydınlatması.': 'روشنایی شبانه‌ی کم‌نور.',
  'Düşüklerin çoğu ilk 12 haftada ve genellikle kromozom farklılıklarına bağlı olarak gerçekleşir.': 'بیشتر سقط‌ها در ۱۲ هفته‌ی اول رخ می‌دهند، معمولاً به دلیل تفاوت‌های کروموزومی.',
  'Düşünce': 'اندیشه',
  'DİKKAT: Yedekte bulunan alanlardaki mevcut kayıtlar yedekteki değerlerle değiştirilecek. Yedekte olmayan alanlardaki kayıtlar korunur. İşlem öncesi yine de mevcut verilerinizi ayrıca yedekleyin.': 'هشدار: ثبت‌های موجود در بخش‌هایی که در پشتیبان هستند با مقادیر پشتیبان جایگزین می‌شوند. ثبت‌های بخش‌هایی که در پشتیبان نیستند حفظ می‌شوند. با این حال پیش از ادامه از داده‌های فعلی جداگانه پشتیبان بگیرید.',
  'DİKKAT: Çocuk 49–72 aylık yakalama aşılaması yaş grubunda olabilir. İkinci suçiçeği dozu için aile hekiminizle görüşün. Bu uyarı aşı yapılmadığı anlamına gelmez.': 'توجه: کودک ممکن است در گروه واکسیناسیون جبرانی ۴۹ تا ۷۲ ماه باشد. درباره نوبت دوم آبله‌مرغان با پزشک خانواده صحبت کنید. این هشدار به معنای زده نشدن واکسن نیست.',
  'Dışarı çıkarken malzeme taşıma.': 'حمل وسایل هنگام بیرون رفتن.',
  'E-posta adresi': 'نشانی ایمیل',
  'E-posta adresi kayıtlıysa şifre sıfırlama bağlantısı gönderilir.': 'اگر ایمیل ثبت شده باشد، پیوند بازنشانی رمز عبور فرستاده می‌شود.',
  'E-posta doğrulaması gerekebilir.': 'ممکن است تأیید ایمیل لازم باشد.',
  'Ebedi, ölümsüz': 'جاودان، نامیرا',
  'Ebedi; Allah’ın adlarından': 'صمد؛ از نام‌های خدا',
  'Ebeveyn tükenmişliği': 'فرسودگی والدینی',
  'Ebeveynlerle soru sor, deneyim paylaş; moderasyonlu ve güvenli topluluk.': 'از والدین بپرسید و تجربه‌ها را به اشتراک بگذارید؛ جامعه‌ای امن و تحت نظارت.',
  'Eczacına gebe olduğunu mutlaka söyle.': 'همیشه به داروساز بگویید باردار هستید.',
  'Ege denizi; yaşlı, olgun': 'دریای اژه؛ بزرگ‌تر، پخته',
  'Egzama kuru, kaşıntılı, kırmızı alanlarla görülür ve tekrarlayabilir.': 'اگزما به‌صورت لکه‌های خشک، خارش‌دار و قرمز ظاهر می‌شود و ممکن است عود کند.',
  'Egzamada akıntı, kabuklanma veya yoğun kaşıntı.': 'ترشح، دلمه یا خارش شدید همراه با اگزما.',
  'Egzamada banyodan hemen sonra parfümsüz nemlendirici sür.': 'برای اگزما، بلافاصله پس از حمام مرطوب‌کننده‌ی بدون عطر بزنید.',
  'Egzersiz': 'ورزش',
  'Egzersiz gebelik diyabeti riskini azaltabilir, sırt ağrısını hafifletebilir.': 'ورزش می‌تواند خطر دیابت بارداری را کم و کمردرد را تسکین دهد.',
  'Egzersiz sırasında kanama, su gelmesi, göğüs ağrısı, baş dönmesi, ağrılı kasılma: dur ve başvur.': 'خونریزی، نشت مایع، درد قفسه‌ی سینه، سرگیجه یا انقباضات دردناک هنگام ورزش: متوقف شوید و بررسی شوید.',
  'Ek enerji ihtiyacı ilk üç ayda çok azdır, sonraki aylarda günde yaklaşık 300–450 kcal artar.': 'نیاز انرژی اضافه در سه‌ماهه‌ی اول بسیار کم است و بعدها حدود ۳۰۰–۴۵۰ کیلوکالری در روز افزایش می‌یابد.',
  'Ek gıda': 'غذای کمکی',
  'Ek gıda döneminde uygun doku, hijyen ve alerjenleri göz önünde bulundurun. Boğulma riski taşıyan yiyeceklerden kaçının.': 'در دوره غذای کمکی به بافت مناسب، بهداشت و آلرژن‌ها توجه کنید. از غذاهایی که خطر خفگی دارند پرهیز کنید.',
  'Ek gıda: {0} kayıt': 'غذای کمکی: {0} ثبت',
  'Ek gıdaya 6. ay civarında, bebek hazır olduğunda başlanır; anne sütü 1 yaşına kadar ana besin olmaya devam eder.': 'غذای کمکی حدود ۶ ماهگی و وقتی نوزاد آماده است شروع می‌شود؛ شیر مادر تا ۱ سالگی غذای اصلی می‌ماند.',
  'Ek gıdaya geçiş': 'شروع غذای کمکی',
  'Ek gıdaya geçişte kabızlık sıklaşabilir.': 'با شروع غذای کمکی یبوست ممکن است شایع‌تر شود.',
  'Ek gıdaya geçtiyse su ve lifli besinler (erik, armut, sebze püreleri) ver.': 'اگر غذای کمکی شروع شده، آب و غذاهای پرفیبر (آلو، گلابی، پوره‌ی سبزیجات) بدهید.',
  'Ek gıdaya hazırlık belirtilerini ve yeni besinleri not edin. Boğulma riskini azaltan uygun kıvam ve güvenli oturma önemlidir.': 'نشانه‌های آمادگی برای غذای جامد و غذاهای جدید را یادداشت کنید. بافت مناسبی که خطر خفگی را کم کند و نشستن ایمن مهم‌اند.',
  'Ek gıdaya küçük miktarlarla başlayın. Demir içeren besinlere, farklı tatlara ve uygun dokulara yer verin. Anne sütü veya formül sürer.': 'غذای جامد را با مقدار کم شروع کنید. غذاهای حاوی آهن، طعم‌های مختلف و بافت مناسب را بگنجانید. شیر مادر یا شیر خشک ادامه دارد.',
  'Ek gıdaya uygun kaşık seçenekleri.': 'گزینه‌های قاشق مناسب غذای جامد.',
  'Ek yaş grubu önerileri': 'پیشنهادهای گروه‌های سنی دیگر',
  'Ek çocukların ad ve doğum tarihleri': 'نام و تاریخ تولد فرزندان دیگر',
  'Ekim': 'اکتبر',
  'Ekle': 'افزودن',
  'Eklenmiş şekerin günlük enerjinin %10\'undan azı (tercihen %5) olması önerilir.': 'شکر افزوده باید کمتر از ۱۰٪ (ترجیحاً ۵٪) انرژی روزانه باشد.',
  'Ekmek': 'نان',
  'Ekmek arasında veya roka salatası ile servis edin.': 'لای نان یا با سالاد منداب سرو کنید.',
  'Ekmeği tost makinesinde hafifçe kızartın.': 'نان را در توستر کمی برشته کنید.',
  'Ekran': 'نمایشگر',
  'Ekran kısıtlandığında aşırı öfke, uyku ve sosyal ilişki sorunları varsa uzmana danış.': 'اگر محدود کردن صفحه‌نمایش خشم شدید ایجاد می‌کند یا مشکلات خواب یا اجتماعی هست، به متخصص مراجعه کنید.',
  'Ekran süresi': 'زمان صفحه‌نمایش',
  'Ekran yerine birlikte oyun ve açık havada hareket tercih et.': 'بازی با هم و تحرک در فضای باز را به صفحه‌نمایش ترجیح دهید.',
  'Ekranlara tek yerden ulaş': 'دسترسی به همه صفحه‌ها از یک جا',
  'Ekransız alanlar belirle: yemek masası ve yatak odası.': 'مناطق بدون صفحه‌نمایش تعیین کنید: میز غذا و اتاق خواب.',
  'Ekransız mola': 'استراحت بدون صفحه‌نمایش',
  'Ekranı sakinleştirme aracı olarak kullanmamaya çalış.': 'سعی کنید از صفحه‌نمایش برای آرام کردن کودک استفاده نکنید.',
  'Eksik entegrasyon': 'یکپارچه‌سازی ناقص',
  'Eksik içerik': 'محتوای ناقص',
  'Eksik malzeme: {0}': 'ماده کمبود: {0}',
  'Eksikleri alışveriş listesine ekle': 'افزودن کمبودها به فهرست خرید',
  'Eksikleri otomatik seç': 'انتخاب خودکار کمبودها',
  'Eksiklerin kategori dağılımı:': 'کمبودها بر اساس دسته:',
  'El kavrama refleksi gelişir; saçlar uzar.': 'رفلکس چنگ زدن رشد می‌کند؛ موها بلندتر می‌شوند.',
  'El kremi': 'کرم دست',
  'El sallayarak selamlaşmayı canlandırın.': 'سلام کردن با دست تکان دادن را با هم اجرا کنید.',
  'El ve tırnak bakımı': 'مراقبت از دست و ناخن',
  'El yıkama, diş fırçalama ve günlük öz bakım rutinlerini birlikte uygulayın. Tuvalet alışkanlığında hazır oluşa saygı gösterin.': 'شستن دست، مسواک زدن و روال‌های مراقبت روزانه را با هم انجام دهید. در مورد عادت توالت به آمادگی احترام بگذارید.',
  'El yıkamayı alışkanlık hâline getir.': 'شستن دست‌ها را عادت کنید.',
  'El, ayak ve burun gibi bölümleri adlandırın.': 'اعضایی مثل دست، پا و بینی را نام ببرید.',
  'El-ayak-ağız hastalığı, suçiçeği, kızamıkçık, grip ve mide-bağırsak enfeksiyonları sık görülür.': 'بیماری دست و پا و دهان، آبله‌مرغان، رزئولا، آنفلوانزا و عفونت‌های گوارشی شایع‌اند.',
  'Ela gözlü nur': 'نور میشی‌چشم',
  'Ela ve su gibi duru': 'میشی و زلال چون آب',
  'Eldiven': 'دستکش',
  'Elektrik güvenliğinde profesyonel önerilere uyun.': 'درباره‌ی ایمنی برق از توصیه‌ی متخصص پیروی کنید.',
  'Elektrik prizleri için koruma.': 'محافظ پریزهای برق.',
  'Elektrik veya kimyasal yanık, nefes darlığı: 112.': 'سوختگی الکتریکی یا شیمیایی، تنگی نفس: با شماره‌ی اورژانس محلی تماس بگیرید.',
  'Elif’in nuru': 'نور الف',
  'Elleri sık yıka; hasta kişilerin bebeği öpmesine izin verme.': 'مرتب دست‌ها را بشویید؛ نگذارید افراد بیمار نوزاد را ببوسند.',
  'Ellerini yıka; kaynatılıp 70 °C civarına soğutulmuş su kullan.': 'دست‌هایتان را بشویید؛ از آبی استفاده کنید که جوشیده و تا حدود ۷۰ °C خنک شده است.',
  'Elleriniz': 'دست‌های شما',
  'Ellerinizi yıkadıktan sonra nemlendirin. Tırnakları temiz ve kısa tutun; keskin aletlerle tırnak etini zorlamayın.': 'پس از شستن دست‌ها را مرطوب کنید. ناخن‌ها را تمیز و کوتاه نگه دارید؛ کوتیکول را با ابزار تیز فشار ندهید.',
  'Ellerinizle yumuşak ritimler oluşturun.': 'با دست‌هایتان ریتم‌های آرام بسازید.',
  'Ellerle keşif ve birlikte etkileşim': 'کاوش با دست‌ها و تعامل با هم',
  'Elma; alımlı': 'سیب؛ دلربا',
  'Elmalı yulaf lapası': 'فرنی جو دوسر با سیب',
  'Elmayı rendeleyin.': 'سیب را رنده کنید.',
  'Elçi kadın; ülkeyi temsil eden': 'سفیر زن؛ نماینده‌ی کشور',
  'Embriyo dönemi sona erer, "fetüs" dönemi başlar; hayati organlar yerini almıştır.': 'مرحله‌ی رویانی تمام و مرحله‌ی «جنینی» شروع می‌شود؛ اندام‌های حیاتی سر جایشان هستند.',
  'Emekleme ve tutunarak kalkma dönemi: priz kapakları, merdiven kapısı, köşe koruyucu, mobilyaları duvara sabitleme. Yürüteç kullanma.': 'مرحله‌ی چهار دست و پا و ایستادن با گرفتن: محافظ پریز، دروازه‌ی پله، محافظ گوشه، ثابت کردن مبلمان به دیوار. از روروئک استفاده نکنید.',
  'Emekler; tutunarak ayağa kalkmayı dener. Başparmak ve işaret parmağıyla küçük nesneleri tutmaya başlar. "baba", "mama" heceleri.': 'چهار دست و پا می‌رود؛ سعی می‌کند با گرفتن بایستد. شروع به برداشتن اشیای کوچک با شست و اشاره می‌کند. هجاهایی مثل «بابا»، «ماما».',
  'Emicilik': 'جذب',
  'Emmede isteksizlik, sürekli uyku hâli veya uyandırılamama.': 'بی‌میلی به شیر خوردن، خواب‌آلودگی دائمی یا بیدار نشدن.',
  'Emniyet kemeri': 'کمربند ایمنی',
  'Emniyet kemeri karnın altından ve göğüslerin arasından geçecek şekilde takılmalıdır.': 'کمربند ایمنی باید زیر شکم و بین سینه‌ها قرار گیرد.',
  'Emzik': 'پستانک',
  'Emzik bebeği rahatlatabilir ve uykuda kullanımı ABÖS riskini azaltabilir; doğru zamanlama önemlidir.': 'پستانک می‌تواند نوزاد را آرام کند و استفاده از آن هنگام خواب ممکن است خطر SIDS را کاهش دهد؛ زمان شروع مهم است.',
  'Emzik kullanımı': 'استفاده از پستانک',
  'Emzik sonrası ağızda beyaz plaklar (pamukçuk) görülürse.': 'اگر لکه‌های سفید (برفک) در دهان ظاهر شد.',
  'Emzik uyku sırasında verilebilir; emzirme oturduktan sonra (genellikle 3–4. hafta) başlamak önerilir.': 'هنگام خواب می‌توان پستانک داد؛ بهتر است پس از جا افتادن شیردهی (معمولاً هفته‌ی ۳–۴) شروع شود.',
  'Emzirdiğin tarafa dokun; taraf değiştirince diğerine dokunman yeter. Bitirince kayıt beslenme günlüğüne eklenir.': 'روی سمتی که شیر می‌دهید بزنید؛ هنگام عوض کردن سمت فقط روی دیگری بزنید. در پایان ثبت به دفترچه تغذیه افزوده می‌شود.',
  'Emziren annelerde östrojensiz yöntemler tercih edilir.': 'برای مادران شیرده روش‌های بدون استروژن ترجیح داده می‌شوند.',
  'Emziren annenin beslenmesi': 'تغذیه‌ی مادران شیرده',
  'Emzirme': 'شیردهی',
  'Emzirme / besleme sorularımı not ettim': 'پرسش‌هایم درباره شیردهی / تغذیه را یادداشت کرده‌ام',
  'Emzirme Yastığı': 'بالش شیردهی',
  'Emzirme döneminde enerji ve sıvı ihtiyacı artar; özel bir diyet çoğu zaman gerekmez.': 'در شیردهی نیاز به انرژی و مایعات بیشتر می‌شود؛ معمولاً رژیم خاصی لازم نیست.',
  'Emzirme günde yaklaşık 450–500 kcal ek enerji gerektirir.': 'شیردهی روزانه حدود ۴۵۰–۵۰۰ کیلوکالری اضافه نیاز دارد.',
  'Emzirme hakkında bilgi edin; uygulamadaki rehberden başlayabilirsin.': 'درباره‌ی شیردهی اطلاعات کسب کنید؛ می‌توانید با راهنمای برنامه شروع کنید.',
  'Emzirme oturana kadar (genellikle 3–4 hafta) emzik vermemek önerilir.': 'توصیه می‌شود تا جا افتادن شیردهی (معمولاً ۳–۴ هفته) پستانک داده نشود.',
  'Emzirme sonrası birkaç damla sütü meme ucuna sürüp kurumaya bırak.': 'پس از شیردهی چند قطره شیر روی نوک پستان بمالید و بگذارید خشک شود.',
  'Emzirme sonrası sağmak üretimi artırabilir.': 'دوشیدن پس از شیردهی می‌تواند تولید را افزایش دهد.',
  'Emzirme sonrası soğuk kompres ödeme iyi gelebilir.': 'کمپرس سرد پس از شیردهی ممکن است تورم را کم کند.',
  'Emzirme sütyeni': 'سوتین شیردهی',
  'Emzirme sırasında rahat pozisyon ve etkili kavrama önemlidir. Sürekli ağrı, ateş veya memede kızarıklık varsa sağlık uzmanıyla görüşün. Beslenme ve sıvı ihtiyacınızı ihmal etmeyin.': 'وضعیت راحت و گرفتن درست پستان در شیردهی مهم است. اگر درد مداوم، تب یا قرمزی پستان دارید با کادر درمان صحبت کنید. نیاز خود به غذا و مایعات را فراموش نکنید.',
