  'Gebelik öncesi kontrol için kadın doğum uzmanına veya aile hekimine başvur.': 'برای معاینه‌ی پیش از بارداری به متخصص زنان یا پزشک خانواده مراجعه کنید.',
  'Gebelik, doğum sonrası dönem veya kronik hastalıkta kişisel öneri alın.': 'در بارداری، پس از زایمان یا در صورت بیماری مزمن توصیه‌ی شخصی بگیرید.',
  'Gebelik, emzirme ve bebeklik döneminde vegan beslenme uzman eşliğinde planlanmalıdır.': 'رژیم وگان در بارداری، شیردهی و نوزادی باید با متخصص برنامه‌ریزی شود.',
