  'Göbek kordonu bakımı': 'مراقبت از بند ناف',
  'Göbek kordonu genellikle 1–3 hafta içinde kuruyup düşer; temiz ve kuru tutmak yeterlidir.': 'باقی‌مانده‌ی بند ناف معمولاً ظرف ۱–۳ هفته خشک می‌شود و می‌افتد؛ تمیز و خشک نگه داشتن آن کافی است.',
  'Gök': 'آسمان',
