  'Günlük mama miktarı • son 7 gün': 'مقدار روزانه شیر خشک • ۷ روز اخیر',
  'Günlük notlarım': 'یادداشت‌های روزانه من',
  'Günlük okunamadı; kayıtlar korunuyor.': 'دفترچه خوانده نشد؛ ثبت‌ها حفظ شد.',
  'Günlük ortalama • son 7 gün': 'میانگین روزانه • ۷ روز اخیر',
  'Günlük rahat kombin': 'لباس روزمره‌ی راحت',
  'Günlük rutin listesi bozuk': 'فهرست روال روزانه خراب است',
  'Günlük rutinlerde bağımsızlık denemeleri': 'تجربه‌ی استقلال در روال‌های روزمره',
  'Günlük sesleri taklit ederek karşılıklı tekrar edin.': 'صداهای روزمره را تقلید و به نوبت تکرار کنید.',
  'Günlük su taşımaya yardımcı.': 'به حمل آب در طول روز کمک می‌کند.',
  'Günlük sözcükleri, jestleri, hareketi ve öz bakım denemelerini oyun içinde gözlemleyin.': 'کلمات روزمره، اشاره‌ها، حرکت و تلاش‌های مراقبت از خود را از طریق بازی مشاهده کنید.',
  'Günlük takip': 'پیگیری روزانه',
  'Günlük veya sağlık kayıtları doğrulanamadı; doğum tarihi değiştirilmedi.': 'ثبت‌های دفترچه یا سلامت تأیید نشد؛ تاریخ تولد تغییر نکرد.',
  'Günlük yaşam günlüğü': 'دفترچه زندگی روزمره',
  'Günlük yaşam kayıtları': 'ثبت‌های زندگی روزمره',
  'Günlük yaşam sorumlulukları, anlatım, sayı ve ses oyunlarıyla okul öncesi becerileri destekleyin.': 'از مهارت‌های پیش‌دبستانی با مسئولیت‌های روزمره، قصه‌گویی و بازی‌های عدد و صدا حمایت کنید.',
  'Günlük yaşam önerileri': 'نکات زندگی روزمره',
  'Günlük yaşamı ciddi etkileyen belirtiler.': 'علائمی که به‌شدت بر زندگی روزمره اثر می‌گذارند.',
  'Günlük yaşamı etkileyen pelvik ağrı.': 'درد لگن که بر زندگی روزمره اثر می‌گذارد.',
  'Günlük yaşamı uzun süre etkileyen yas ve umutsuzluk.': 'سوگ و ناامیدی که مدت طولانی بر زندگی روزمره اثر می‌گذارد.',
  'Günlük yemek önerilerim': 'ایده‌های غذای روزانه من',
  'Günlük zaman planı': 'برنامه‌ی زمانی روزانه',
  'Günlük özet ve doktor raporu': 'خلاصه روزانه و گزارش پزشک',
  'Günün bir olayını hatırlayıp anlatın.': 'چیزی را که امروز اتفاق افتاد به یاد آورید و تعریف کنید.',
  'Günün en önemli üç işini belirleyin. Beklenmedik durumlar için takvimde esnek zaman bırakın.': 'سه کار مهم روز را انتخاب کنید. در تقویم برای پیشامدها زمان انعطاف‌پذیر بگذارید.',
  'Günün kayıtları': 'ثبت‌های امروز',
  'Günün sevilen anlarını kısa cümlelerle paylaşın.': 'لحظه‌های محبوب روز را با جمله‌های کوتاه با هم در میان بگذارید.',
  'Günün sonunda nasıl hissettiğinizi birkaç kelimeyle yazın. Duygunuzu değiştirmeye zorlamadan fark etmeye çalışın.': 'در پایان روز احساستان را در چند کلمه بنویسید. سعی کنید احساس را ببینید بی‌آنکه خودتان را مجبور به تغییرش کنید.',
  'Günün tarifi': 'دستور روز',
