  'Güvenli uyku, bal, şeker ve ekran gibi konularda öneriler zaman içinde değişmiştir.': 'توصیه‌ها درباره‌ی خواب ایمن، عسل، شکر و صفحه‌نمایش در طول زمان تغییر کرده‌اند.',
