  'Hava koşullarını dikkate alın.': 'وضع هوا را در نظر بگیرید.',
  'Hava temizleyici': 'دستگاه تصفیه‌ی هوا',
  'Hava ve fiziksel koşullara göre hareket edin.': 'بر اساس هوا و وضعیت جسمی‌تان حرکت کنید.',
  'Hava yastığı önündeki koltuğa arkaya bakan bebek koltuğu asla takılmamalıdır.': 'هرگز صندلی نوزاد رو به عقب را جلوی کیسه‌ی هوای فعال نصب نکنید.',
  'Hava yolu tıkanması dakikalar içinde hayati tehlike yaratır; temel ilk yardımı bilmek hayat kurtarır.': 'انسداد راه هوایی ظرف چند دقیقه تهدیدکننده‌ی حیات می‌شود؛ دانستن کمک‌های اولیه‌ی پایه جان نجات می‌دهد.',
  'Havale, morarma, döküntü (basmakla solmayan), ense sertliği, çok halsizlik: 112.': 'تشنج، کبود شدن، بثوراتی که با فشار محو نمی‌شود، سفتی گردن، ضعف شدید: با شماره‌ی اورژانس محلی تماس بگیرید.',
  'Havucu rendeleyip yağda kısa süre soteleyin.': 'هویج را رنده و کوتاه در روغن تفت دهید.',
  'Havuç ve kabağı yağda 3 dakika soteleyin.': 'هویج و کدو را ۳ دقیقه در روغن تفت دهید.',
  'Havuç ve patatesi küp doğrayıp 5 dakika soteleyin.': 'هویج و سیب‌زمینی را مکعبی ببرید و ۵ دقیقه تفت دهید.',
  'Havuç, kabak ve biberi ince şeritler hâlinde doğrayın.': 'هویج، کدو و فلفل را نواری نازک ببرید.',
  'Havuç, kabak ve domatesi küçük küpler halinde doğrayın.': 'هویج، کدو و گوجه را مکعب‌های کوچک خرد کنید.',
  'Havuç, kabak, biber ve soğanı 1 yemek kaşığı zeytinyağı, kekik ve yarım çay kaşığı tuzla harmanlayın.': 'هویج، کدو، فلفل و پیاز را با ۱ قاشق غذاخوری روغن زیتون، آویشن و نصف قاشق چای‌خوری نمک مخلوط کنید.',
  'Havuç, lahana': 'هویج، کلم',
  'Havuç, patates ve bezelyeyi ekleyip karıştırın.': 'هویج، سیب‌زمینی و نخودفرنگی را اضافه و هم بزنید.',
  'Havuçları zeytinyağında 3 dakika soteleyin.': 'هویج‌ها را ۳ دقیقه در روغن زیتون تفت دهید.',
  'Hayal gücü': 'تخیل',
  'Hayali oyun, yapboz, oyun hamuru, bisiklet (üç tekerlekli), birlikte yemek hazırlama.': 'بازی وانمودی، پازل، خمیربازی، سه‌چرخه، آشپزی با هم.',
  'Hayali yemek hazırlama oyunu oynayın.': 'آماده کردن غذای خیالی را بازی کنید.',
  'Hayati tehlike: 112.': 'خطر جانی: با شماره‌ی اورژانس محلی تماس بگیرید.',
  'Hayvan resimleri': 'تصاویر حیوانات',
  'Hayvan sesleri': 'صدای حیوانات',
  'Hayvansal kaynaklı demir (kırmızı et, tavuk, balık) bitkisel demirden daha iyi emilir.': 'آهن منابع حیوانی (گوشت قرمز، مرغ، ماهی) بهتر از آهن گیاهی جذب می‌شود.',
  'Hayırlı': 'خیر، نیک',
  'Hazine sepeti': 'سبد گنج',
  'Haziran': 'ژوئن',
  'Hazır 7 günlük menü': 'منوی آماده ۷ روزه',
  'Hazır gıdalar gizli şeker ve tuzun en büyük kaynağıdır.': 'غذاهای آماده بزرگ‌ترین منبع شکر و نمک پنهان‌اند.',
  'Hazır olma belirtileri varsa ek gıdaya başla: tek tek, birkaç gün arayla, püre kıvamında. Demirden zengin besinler (et, yumurta sarısı, mercimek) öncelikli. Tuz, şeker ve bal eklenmez; anne sütü devam eder.': 'اگر نشانه‌های آمادگی هست، غذای کمکی را شروع کنید: یکی‌یکی، با فاصله‌ی چند روز، به‌شکل پوره. غذاهای سرشار از آهن (گوشت، زرده‌ی تخم‌مرغ، عدس) در اولویت‌اند. نمک، شکر یا عسل اضافه نمی‌شود؛ شیردهی ادامه دارد.',
  'Hazır olma belirtileri: destekle dik oturma, başını tutma, yiyeceğe ilgi, dili ile dışarı itme refleksinin azalması.': 'نشانه‌های آمادگی: نشستن صاف با تکیه، نگه داشتن ثابت سر، علاقه به غذا، ضعیف شدن رفلکس بیرون راندن زبان.',
  'Hazır ve işlenmiş gıdaları azalt; etiket okuma alışkanlığı edin.': 'غذاهای آماده و فرآوری‌شده را کم کنید؛ خواندن برچسب را عادت کنید.',
  'Hazırlama süresi (dk)': 'زمان آماده‌سازی (دقیقه)',
  'Hazırlanan mama oda sıcaklığında en fazla 2 saat bekleyebilir; artan kısmı dökülmelidir.': 'شیر خشک آماده‌شده حداکثر ۲ ساعت در دمای اتاق می‌ماند؛ باقی‌مانده باید دور ریخته شود.',
  'Hazırlandıktan hemen sonra soğuk servis edin.': 'بلافاصله پس از آماده شدن سرد سرو کنید.',
