  'Hekim önerdiyse adrenalin oto-enjektörünü her zaman yanında taşı.': 'اگر پزشک توصیه کرده، قلم تزریق خودکار آدرنالین را همیشه همراه داشته باشید.',
  'Hekiminin önerdiği zamanda (örneğin kasılmalar 5 dakikada bir, 1 dakika sürüp 1 saat devam ettiğinde) hastaneye git.': 'زمانی که پزشک گفته به بیمارستان بروید (مثلاً وقتی انقباضات هر ۵ دقیقه، به مدت ۱ دقیقه و به مدت ۱ ساعت ادامه دارد).',
  'Hemen tüketin; bekleyecekse buzdolabında en fazla 12 saat saklayın.': 'فوراً بخورید؛ اگر باید بماند، حداکثر ۱۲ ساعت در یخچال نگه دارید.',
