  'Henüz kayıt yok. Sağ alttan yeni kayıt ekleyin.': 'هنوز ثبتی نیست. از پایین سمت راست ثبت جدید بیفزایید.',
  'Henüz kayıt yok. Sağlık kuruluşunuzdan aldığınız tarihleri ekleyebilirsiniz.': 'هنوز ثبتی نیست. می‌توانید تاریخ‌هایی را که از مرکز درمانی گرفته‌اید اضافه کنید.',
  'Henüz kayıt yok. İlk kaydını ekleyebilirsin.': 'هنوز ثبتی نیست. می‌توانید اولین ثبت را اضافه کنید.',
  'Henüz kontrol eklenmedi. Tarih ve açıklama ekleyebilirsin.': 'هنوز معاینه‌ای افزوده نشده. می‌توانید تاریخ و توضیح اضافه کنید.',
