  'Hepsini tamamen yumuşayana kadar pişirin.': 'همه را بپزید تا کاملاً نرم شود.',
  'Her aile için bir seçenek': 'گزینه‌ای برای هر خانواده',
  'Her ay için gelişim, beslenme, uyku, oyun, bakım ve güvenlik. İçerikler genel öneridir; aylık gelişim kontrol listesi değildir.': 'رشد، تغذیه، خواب، بازی، مراقبت و ایمنی برای هر ماه. محتوا توصیه کلی است؛ چک‌لیست ماهانه رشد نیست.',
  'Her ay, adet bitiminden birkaç gün sonra. Ele gelen kitle, meme başı akıntısı ya da ciltte çekinti varsa doktora git.': 'هر ماه، چند روز پس از پایان قاعدگی. اگر توده، ترشح از نوک پستان یا فرورفتگی پوست حس کردید به پزشک مراجعه کنید.',
  'Her bebek kendi hızında gelişir; birkaç haftalık farklar olağandır.': 'هر نوزاد با سرعت خودش رشد می‌کند؛ تفاوت چند هفته‌ای طبیعی است.',
  'Her bebeğin gelişimini ve günlük kayıtlarını ayrı ayrı takip et.': 'رشد و ثبت‌های روزانه هر کودک را جداگانه پیگیری کنید.',
  'Her boğulma olayından sonra, cisim çıksa bile sağlık kontrolü.': 'پس از هر خفگی، حتی اگر جسم بیرون آمده، معاینه‌ی پزشکی لازم است.',
  'Her ekrandan geri dönüş ve yönlendirme döngüsü test edildi': 'بازگشت و پیمایش از هر صفحه آزمایش شد',
  'Her emzirmede yanında bir bardak su bulundur.': 'در هر شیردهی یک لیوان آب کنار خود داشته باشید.',
  'Her gün aynı saatte hatırlat': 'هر روز در همان ساعت یادآوری کن',
  'Her gün aynı saatte, sakin bir uyku rutini uygula.': 'روال آرام خواب را هر روز در همان ساعت نگه دارید.',
  'Her gün bebeğin en hareketli olduğu saatlerde dikkatle takip et.': 'هر روز در ساعت‌هایی که نوزاد فعال‌تر است توجه کنید.',
  'Her gün birlikte kitap oku.': 'هر روز با هم کتاب بخوانید.',
  'Her gün hatırlat': 'هر روز یادآوری کن',
  'Her gün kendine ayırdığın kısa bir zaman dilimi belirle.': 'هر روز زمان کوتاهی را برای خودتان کنار بگذارید.',
  'Her gün kendine kısa bir mola ver.': 'هر روز به خودتان استراحتی کوتاه بدهید.',
  'Her gün tekrarlanan ilaç ve vitamin hatırlatmaları': 'یادآورهای روزانه تکراری دارو و ویتامین',
  'Her iki yüzü kızarıp içi tamamen pişene kadar pişirin.': 'بپزید تا هر دو طرف طلایی و داخلش کاملاً پخته شود.',
  'Her ikisi': 'هر دو',
  'Her kontrolde tansiyon ölçümü ve idrar tahlili bu nedenle yapılır.': 'به همین دلیل در هر ویزیت فشار خون و آزمایش ادرار بررسی می‌شود.',
  'Her uykuda sırtüstü yatırın; düz ve sert uyku yüzeyinde yastık, oyuncak ve gevşek örtü bulundurmayın. Uyku süresi bebekler arasında değişir.': 'نوزاد را در هر خواب به پشت بخوابانید؛ روی سطح خواب صاف و سفت بدون بالش، اسباب‌بازی یا روانداز شل. مدت خواب در نوزادان متفاوت است.',
  'Her yufkayı ikiye kesin; yarım yufkayı sosla ıslatıp kenarına harç koyun, rulo yapıp yuvarlak tepsiye spiral dizin.': 'هر یوفکا را دو نیم کنید؛ نیم‌ورق را با سس خیس کنید، مواد را لبه‌اش بگذارید، رول کنید و به‌صورت مارپیچ در سینی گرد بچینید.',
  'Her şey bir arada 💗': 'همه در یک جا 💗',
  'Her şeyi aynı anda yapmak mümkün değildir; öncelik belirlemek stresi azaltır.': 'نمی‌توانید همه‌چیز را یک‌جا انجام دهید؛ اولویت‌بندی استرس را کم می‌کند.',
