  'Hesap oluşturup kayıtlarını cihazlar arasında güvenle eşitleme.': 'حساب بسازید و ثبت‌هایتان را به‌طور امن بین دستگاه‌ها همگام کنید.',
  'Hesap ve üyelik akışları': 'مسیرهای حساب و عضویت',
