  'His': 'احساس',
  'Hiç hareket hissedilmemesi.': 'اصلاً هیچ حرکتی احساس نکردن.',
  'Hiçbir şey tutamayacak kadar kusma, idrarın azalması.': 'استفراغ به حدی که چیزی نگه ندارید، ادرار کمتر.',
  'Horlama, uykuda nefes alırken çekilme veya hırıltı sürekli ise.': 'اگر خروپف، فرو رفتن قفسه‌ی سینه هنگام تنفس در خواب یا خس‌خس دائمی است.',
