  'Kapağı kapalı 40 dakika, ardından kapağı açık 15 dakika pişirin.': '۴۰ دقیقه با در بسته و سپس ۱۵ دقیقه با در باز بپزید.',
  'Kapağı kapalı kısık ateşte 15 dakika pişirip 5 dakika dinlendirin.': 'با در بسته روی حرارت کم ۱۵ دقیقه بپزید و ۵ دقیقه دم بگذارید.',
  'Kapağı kapalı kısık ateşte et yumuşayana kadar 35–50 dakika pişirin.': 'با در بسته روی حرارت کم ۳۵–۵۰ دقیقه بپزید تا گوشت نرم شود.',
  'Kapağı kapalı olarak patlıcanlar yumuşayana kadar 25 dakika pişirin.': 'با در بسته ۲۵ دقیقه بپزید تا بادمجان‌ها نرم شوند.',
  'Kapağı kapalı şekilde bamyalar yumuşayana kadar 25-30 dakika pişirin.': 'با در بسته ۲۵-۳۰ دقیقه بپزید تا بامیه‌ها نرم شوند.',
