  'Konuşabileceğin tempoda kal; bol su iç, aşırı ısınmaktan kaçın.': 'با سرعتی ورزش کنید که هنوز بتوانید صحبت کنید؛ آب فراوان بنوشید و از گرمازدگی پرهیز کنید.',
  'Konuşma gecikmesi': 'تأخیر گفتار',
  'Konuşma gelişimi çocuktan çocuğa değişir; ancak bazı işaretler erken değerlendirme gerektirir.': 'رشد گفتار از کودکی به کودک دیگر فرق می‌کند، اما برخی نشانه‌ها نیاز به ارزیابی زودهنگام دارند.',
  'Konuşurken çocuğun seviyesine in ve yüzünü görmesini sağla.': 'هنگام صحبت هم‌سطح کودک شوید و بگذارید چهره‌تان را ببیند.',
  'Kopabilecek küçük parçaları kontrol edin.': 'قطعات کوچکی را که ممکن است جدا شوند بررسی کنید.',
  'Kopyala': 'کپی',
  'Kordon 3 haftada düşmezse veya göbekte sürekli kanama olursa.': 'اگر بند ناف تا ۳ هفتگی نیفتاده یا ناف مدام خونریزی می‌کند.',
  'Kordon düşene kadar küvete daldırmak yerine silme banyosu yap.': 'تا افتادن بند ناف، به‌جای فرو بردن در وان، با اسفنج بشویید.',
  'Kordon düşene kadar silme banyosu yeterlidir.': 'تا افتادن بند ناف، شستشو با اسفنج کافی است.',
  'Kordon kurudukça koyulaşır ve kendiliğinden düşer.': 'بند ناف با خشک شدن تیره می‌شود و خودبه‌خود می‌افتد.',
  'Kordonu kuru ve açıkta tut; bezi göbeğin altında kalacak şekilde katla.': 'بند ناف را خشک و باز نگه دارید؛ پوشک را زیر ناف تا کنید.',
  'Korkutan; Dede Korkut': 'ترساننده؛ دده قورقود',
  'Koruyan, kollayan': 'نگهبان، حامی',
  'Koruyan; neşeli': 'نگهبان؛ شاد',
  'Kova, küvet ve havuzlar küçük çocuklar için risklidir.': 'سطل، وان و استخر برای کودکان خردسال خطرناک‌اند.',
  'Koyu idrar, baş dönmesi; bebekte ıslak bezin azalması.': 'ادرار تیره، سرگیجه؛ در نوزاد پوشک خیس کمتر.',
  'Kozmetik': 'آرایشی',
  'Kozmetik & Bakım': 'آرایشی و مراقبتی',
  'Koşmaya çalışır; yardım alarak merdiven çıkar. Resimdeki nesneleri gösterir, oyuncak bebeği besler.': 'سعی می‌کند بدود؛ با کمک از پله بالا می‌رود. به اشیا در تصاویر اشاره می‌کند، به عروسک غذا می‌دهد.',
  'Kraliçe, güzel kadın': 'ملکه، زن زیبا',
  'Kraliçe, hükümdar kadın': 'ملکه، زن فرمانروا',
  'Kraliçem, hükümdar eşi': 'ملکه‌ی من، همسر فرمانروا',
  'Kraliçenin nuru': 'نور ملکه',
  'Kremalı mantar çorbası': 'سوپ قارچ خامه‌ای',
  'Kremayı kaynatmadan, hafif fokurdayacak şekilde ısıtın.': 'خامه را بدون جوشاندن، تا قل‌قل ملایم گرم کنید.',
  'Kremayı ve limon kabuğunu ekleyin; tuz ve karabiberle tatlandırıp 2 dakika kısık ateşte kaynatın.': 'خامه و پوست لیمو را اضافه کنید؛ با نمک و فلفل مزه‌دار کنید و ۲ دقیقه روی حرارت کم بجوشانید.',
  'Kreş ve okul öncesi dönemde çocuklar sık enfeksiyon geçirir; çoğu kendiliğinden iyileşir.': 'در مهدکودک و پیش‌دبستانی کودکان اغلب عفونت می‌گیرند؛ بیشتر خودبه‌خود بهتر می‌شوند.',
  'Kreş ve okula uyum': 'سازگاری با مهدکودک و مدرسه',
  'Kreşlerin resmî izin ve denetim durumunu kontrol et.': 'مجوز رسمی و وضعیت بازرسی مهدکودک را بررسی کنید.',
  'Kronik hastalık ilaçlarını kendi başına bırakmak da risklidir.': 'قطع خودسرانه‌ی داروهای بیماری‌های مزمن هم خطرناک است.',
  'Kronik hastalıklar ve kullanılan ilaçlar gebelik öncesi gözden geçirilmelidir.': 'بیماری‌های مزمن و داروها باید پیش از بارداری بازبینی شوند.',
  'Kronik hastalıklarım': 'بیماری‌های مزمن من',
  'Kukla sohbeti': 'گفت‌وگو با عروسک',
  'Kuklayla kısa bir konuşma canlandırın.': 'با عروسک گفت‌وگویی کوتاه اجرا کنید.',
  'Kulak': 'گوش',
  'Kulak ağrısı ve göz akıntısı': 'گوش‌درد و چشم چسبناک',
  'Kulak iltihabı genellikle soğuk algınlığından sonra gelişir; huzursuzluk ve kulak çekme görülebilir.': 'عفونت گوش معمولاً پس از سرماخوردگی رخ می‌دهد؛ بی‌قراری و کشیدن گوش دیده می‌شود.',
  'Kulaklar yerine yerleşir ve sesleri algılamaya başlayabilir.': 'گوش‌ها در جای خود قرار می‌گیرند و ممکن است شروع به شنیدن صداها کنند.',
  'Kulaktan akıntı, yüksek ateş veya şiddetli huzursuzluk.': 'ترشح از گوش، تب بالا یا بی‌قراری شدید.',
  'Kulağa pamuklu çubuk sokma, damla koyma (doktor önermedikçe).': 'گوش‌پاک‌کن یا قطره در گوش نگذارید (مگر به توصیه‌ی پزشک).',
  'Kule kurma': 'ساختن برج',
  'Kullandığın ilaçları gebelik olasılığına göre doktoruna sor.': 'در صورت احتمال بارداری، درباره‌ی داروهایی که مصرف می‌کنید از پزشک بپرسید.',
  'Kullandığın tüm ilaç ve takviyelerin listesini doktoruna götür.': 'فهرست همه‌ی داروها و مکمل‌هایتان را نزد پزشک ببرید.',
  'Kullanıcı arama, abonelik gelirleri, içerik editörü ve merkezi ürün yönetimi bu sürümde mevcut değildir.': 'جستجوی کاربران، درآمد اشتراک، ویرایشگر محتوا و مدیریت مرکزی محصولات در این نسخه در دسترس نیست.',
  'Kullanıcı verileri korunarak önceki paket üzerinden yükseltme denendi': 'ارتقا از بسته قبلی با حفظ داده‌های کاربر امتحان شد',
  'Kullanılmayan kova ve küvetleri boşalt; havuzların etrafını çit ile çevir.': 'سطل‌ها و وان‌های بلااستفاده را خالی کنید؛ دور استخر حصار بکشید.',
  'Kullanım bilgileri kaydedilemedi': 'اطلاعات مصرف ذخیره نشد',
  'Kullanım talimatlarına ve hijyene uyun.': 'از دستور استفاده و بهداشت پیروی کنید.',
  'Kullanıyorum': 'مصرف می‌کنم',
  'Kumaş': 'پارچه',
  'Kumaşı görüş alanında yavaşça hareket ettirin.': 'پارچه را آرام در میدان دیدش حرکت دهید.',
  'Kundak': 'قنداق',
  'Kurallı basit oyunlar, makasla kesme (çocuk makası), dans, doğa yürüyüşü.': 'بازی‌های ساده‌ی قانون‌دار، بریدن با قیچی کودک، رقص، پیاده‌روی در طبیعت.',
  'Kurtuluş': 'رستگاری',
  'Kuru baklagilleri bir gece önceden ıslatın, suyunu dökerek haşlayın.': 'حبوبات خشک را از شب قبل خیس کنید، آبکش کنید و سپس بپزید.',
  'Kuru dönemden sonra yeniden ıslatma başladıysa.': 'اگر پس از دوره‌ای خشک ماندن، خیس کردن دوباره شروع شود.',
  'Kuru fasulye': 'خوراک لوبیا سفید',
  'Kuru naneyi ekleyip sıcak servis edin.': 'نعناع خشک را اضافه کنید و داغ سرو کنید.',
  'Kuru soğuk': 'سرمای خشک',
  'Kurulum gerekli': 'راه‌اندازی لازم است',
  'Kuruma': 'خشک کردن',
  'Kur’an’da bir sure': 'سوره‌ای در قرآن',
  'Kur’an’da bir sure adı': 'نام سوره‌ای در قرآن',
  'Kuskusla karıştırıp limon suyu ekleyerek servis edin.': 'با کوسکوس مخلوط کنید، آب لیمو بیفزایید و سرو کنید.',
  'Kuskusu kaynar suda paket süresine göre haşlayıp süzün.': 'کوسکوس را طبق بسته در آب جوش بپزید و آبکش کنید.',
  'Kusturmaya çalışmak zararlı olabilir.': 'تلاش برای به استفراغ انداختن کودک ممکن است آسیب‌زا باشد.',
  'Kusursuz, esen': 'بی‌عیب، سالم',
  'Kutlu ay': 'ماه فرخنده',
  'Kutlu er': 'مرد فرخنده',
  'Kutsal, temiz': 'مقدس، پاک',
  'Kutu oyunları, rol yapma, bahçe işleri, kütüphane ziyaretleri.': 'بازی‌های رومیزی، بازی نقش، باغبانی، رفتن به کتابخانه.',
  'Kutuya nesne atma, kaşık-bardakla taklit oyunları, resimdeki nesneyi gösterme.': 'انداختن اشیا در جعبه، بازی‌های تقلید با قاشق و لیوان، اشاره به اشیا در تصاویر.',
  'Kuzey yönü': 'سمت شمال',
  'Kuzeydoğu rüzgârı': 'باد شمال‌شرقی',
  'Kâbus sonrası sakinleştir; gece korkusunda uyandırmaya çalışma, güvenliğini sağla.': 'پس از کابوس آرامش دهید؛ در وحشت شبانه سعی نکنید بیدارش کنید، فقط مراقب امنیتش باشید.',
  'Kâbuslar ve gece korkuları okul öncesi dönemde yaygındır.': 'کابوس و وحشت شبانه در سال‌های پیش‌دبستانی شایع است.',
  'Kâhin kadın': 'زن پیشگو',
  'Kâinat': 'کیهان',
  'Kâğıt havlu': 'دستمال آشپزخانه',
  'Kâğıt içinde pişirme balığın kendi buharında pişmesini sağlar, kurumasını önler.': 'پخت در کاغذ باعث می‌شود ماهی در بخار خودش بپزد و خشک نشود.',
  'Kâğıtların kenarlarını katlayarak kapalı paketler hâline getirin, tepsiye dizin.': 'لبه‌های کاغذ را تا کنید تا بسته‌های بسته درست شود و در سینی بچینید.',
  'Köfteleri ve yağla harmanlanmış patatesleri tepsiye yerleştirin.': 'کوفته‌ها و سیب‌زمینی‌های روغنی را در سینی بچینید.',
  'Kök Türk': 'گوک‌ترک (ترک آسمانی)',
  'Kötü kokulu akıntı, ateş, karında artan ağrı.': 'ترشح بدبو، تب، درد شکم رو به افزایش.',
  'Kötü kokulu, yeşil-sarı veya köpüklü akıntı.': 'ترشح بدبو، سبز-زرد یا کف‌دار.',
  'Köşe koruyucu': 'محافظ گوشه',
  'Küp doğranmış patates ve havucu ekleyin.': 'سیب‌زمینی و هویج مکعبی را اضافه کنید.',
  'Küp doğranmış tavuğu yağda pişirin; iç sıcaklığının 74°C’ye ulaştığını kontrol edin.': 'مرغ مکعبی را در روغن بپزید؛ مطمئن شوید دمای داخلی‌اش به ۷۴ درجه رسیده است.',
  'Kürtçe': 'کردی',
  'Küçük asker': 'سرباز کوچک',
  'Küçük ay, hilal': 'ماه کوچک، هلال',
  'Küçük bir kasede zeytinyağı, limon suyu, limon kabuğu, sarımsak, kekik, tuz ve karabiberi karıştırın.': 'در کاسه‌ای کوچک روغن زیتون، آب و پوست لیمو، سیر، آویشن، نمک و فلفل را مخلوط کنید.',
  'Küçük hedef belirleme': 'تعیین اهداف کوچک',
  'Küçük parça kemiksiz tavuk': 'یک تکه‌ی کوچک مرغ بدون استخوان',
  'Küçük parçaları erişim dışında saklayın.': 'قطعات کوچک را دور از دسترس نگه دارید.',
  'Küçük porsiyonlar sun; yeni besini sevilen bir besinle birlikte ver.': 'وعده‌های کوچک بدهید؛ غذای جدید را همراه غذای محبوبش ارائه کنید.',
  'Küçük tansiyon': 'فشار دیاستولیک',
  'Küçük tansiyon (mmHg)': 'فشار دیاستولیک (میلی‌متر جیوه)',
  'Küçük tansiyonu (30–160 mmHg, büyük tansiyondan küçük) girin.': 'فشار دیاستولیک را وارد کنید (۳۰ تا ۱۶۰ میلی‌متر جیوه، کمتر از سیستولیک).',
  'Küçük tuğ, sancak': 'توق کوچک، پرچم',
  'Küçük ve düzenli molalar uzun vadeli dayanıklılığı artırır.': 'استراحت‌های کوتاه و منظم تاب‌آوری بلندمدت می‌سازند.',
  'Küçük yassı köfteler hazırlayın.': 'به شکل قرص‌های کوچک و پهن درآورید.',
  'Küçük çocuklar sık düşer; çoğu düşme hafiftir ama bazı belirtiler acil değerlendirme gerektirir.': 'کودکان خردسال زیاد زمین می‌خورند؛ بیشتر افتادن‌ها جزئی است، اما برخی نشانه‌ها نیاز به ارزیابی فوری دارند.',
  'Küçük çocuklarda yaralanmaların çoğu evde olur ve büyük kısmı önlenebilir.': 'بیشتر آسیب‌های کودکان خردسال در خانه رخ می‌دهد و بیشترشان قابل پیشگیری است.',
  'Küçük çocukların iştahı günden güne değişir; seçici yeme bu yaşlarda yaygındır.': 'اشتهای کودکان خردسال روزبه‌روز فرق می‌کند؛ بدغذایی در این سنین شایع است.',
  'Kılçıkları pişirmeden önce cımbızla almak servis sırasında kolaylık sağlar.': 'درآوردن تیغ‌ها با موچین پیش از پخت، سرو را آسان‌تر می‌کند.',
  'Kılıf': 'روکش',
  'Kırmızı et, baklagil, yeşil yapraklı sebze gibi demir kaynaklarını tüket.': 'منابع آهن مثل گوشت قرمز، حبوبات و سبزیجات برگ سبز بخورید.',
  'Kırmızı mercimek köftesi': 'کوفته‌ی عدس قرمز',
  'Kısa da olsa ikinize ayırdığınız zamanlar planlayın.': 'برای زمانی فقط دونفره، حتی کوتاه، برنامه بریزید.',
  'Kısa dinlenme araları planlayın; bakım sorumluluklarını paylaşın. Yorgunken bebeğinizle koltukta veya kanepede uyumamaya dikkat edin.': 'استراحت‌های کوتاه برنامه‌ریزی کنید و مراقبت را تقسیم کنید. وقتی خسته‌اید مراقب باشید با کودک روی مبل یا صندلی راحتی خوابتان نبرد.',
  'Kısa hikâye kurma ve neden-sonuç soruları ekleyin.': 'ساختن قصه‌ی کوتاه و سؤال‌های علت و معلول اضافه کنید.',
  'Kısa nefes egzersizleri ve fiziksel aktivite stres tepkisini azaltır.': 'تمرین‌های کوتاه تنفسی و فعالیت بدنی واکنش استرس را کاهش می‌دهند.',
  'Kısa nefes molası': 'استراحت تنفسی کوتاه',
  'Kısa süre desteksiz oturabilir; sesin geldiği yöne döner. Hece tekrarları artar, ayna görüntüsüne ilgi gösterir.': 'مدت کوتاهی بدون تکیه می‌نشیند؛ به سمت منبع صدا برمی‌گردد. غان‌وغون بیشتر می‌شود؛ به تصویرش در آینه علاقه نشان می‌دهد.',
  'Kısa tekrarlar yapın; bebeğin bakışını ve tepkisini takip edin. Nesneleri ağzına götürmesine izin vermeyin.': 'تکرارهای کوتاه انجام دهید؛ نگاه و واکنش‌های نوزاد را دنبال کنید. نگذارید اشیا را به دهان ببرد.',
  'Kısa uyku. Bebeğin uyurken dinlenmeye, yardım istemeye çalış.': 'خواب کوتاه. سعی کنید وقتی کودک می‌خوابد استراحت کنید و کمک بخواهید.',
  'Kısa ve kararlı vedalaş; gizlice ayrılma.': 'کوتاه و با اطمینان خداحافظی کنید؛ یواشکی نروید.',
  'Kısa şekerlemeler bile toparlanmaya yardımcı olur.': 'حتی چرت‌های کوتاه به بازیابی کمک می‌کنند.',
  'Kısa şekerlemeler bile yorgunluğu azaltır.': 'حتی چرت‌های کوتاه خستگی را کم می‌کنند.',
  'Kıskançlık sevginin değil, ilgiyi kaybetme korkusunun işaretidir.': 'حسادت نشانه‌ی کمبود محبت نیست بلکه نشانه‌ی ترس از دست دادن توجه است.',
  'Kısmi': 'ناقص',
  'Kısık ateşte 25-30 dakika pişirip limonla servis edin.': 'روی حرارت کم ۲۵-۳۰ دقیقه بپزید و با لیمو سرو کنید.',
  'Kısık ateşte fasulyeler yumuşayana kadar 35-40 dakika pişirin.': 'روی حرارت کم ۳۵-۴۰ دقیقه بپزید تا لوبیاها نرم شوند.',
  'Kısık ateşte iki tarafını tamamen pişirin.': 'روی حرارت کم هر دو طرف را کاملاً بپزید.',
  'Kısık ateşte karıştırarak 7-8 dakika koyulaştırın.': 'روی حرارت کم ۷-۸ دقیقه هم بزنید تا غلیظ شود.',
  'Kısık ateşte sebzeler yumuşayana kadar 25 dakika pişirin; ılıtarak servis edin.': 'روی حرارت کم ۲۵ دقیقه بپزید تا سبزیجات نرم شوند؛ ولرم سرو کنید.',
  'Kısık ateşte suyunu çekene kadar pişirin; 10 dakika dinlendirin.': 'روی حرارت کم بپزید تا آب کشیده شود؛ ۱۰ دقیقه دم بگذارید.',
  'Kısık ateşte taneler yumuşayıp suyu çekene kadar 15-20 dakika pişirin.': 'روی حرارت کم ۱۵-۲۰ دقیقه بپزید تا دانه‌ها نرم و آب کشیده شود.',
  'Kıvamı püreden başlayıp yaşla birlikte parçalı ve parmak yiyeceklere ilerlet.': 'با پوره شروع کنید و با افزایش سن به بافت‌های تکه‌دار و غذاهای انگشتی برسید.',
  'Kıvrım içlerine yayılan, parlak kırmızı ve kenarında noktacıklar olan pişik mantar kaynaklı olabilir.': 'بثورات قرمز روشن که به چین‌های پوست گسترش یابد و در لبه‌ها نقاط کوچک داشته باشد ممکن است قارچی باشد.',
  'Kıyafet bakım etiketleri': 'برچسب‌های مراقبت از لباس',
