  'Patates graten': 'گراتن سیب‌زمینی',
  'Patates püresi veya mevsim salatası ile sıcak servis edin.': 'داغ با پوره‌ی سیب‌زمینی یا سالاد فصل سرو کنید.',
  'Patates ve soğan halkalarını fırın kabına yayın, 1 yemek kaşığı zeytinyağı ve bir tutam tuzla harmanlayıp fırında 10 dakika ön pişirin.': 'حلقه‌های سیب‌زمینی و پیاز را در ظرف فر پهن کنید، با ۱ قاشق غذاخوری روغن زیتون و کمی نمک مخلوط کنید و ۱۰ دقیقه پیش‌پخت کنید.',
  'Patates, kabak ve biberleri güveç kabına yayın, tuz ve kekik serpin; domatesli sosun yarısını üzerine dökün.': 'سیب‌زمینی، کدو و فلفل‌ها را در ظرف پهن کنید، نمک و آویشن بپاشید؛ نیمی از سس گوجه را رویشان بریزید.',
