  'Patlıcanları küp doğrayıp az yağla 200°C fırında 20 dakika yumuşatın.': 'بادمجان‌ها را مکعبی ببرید و با کمی روغن در فر ۲۰۰ درجه ۲۰ دقیقه نرم کنید.',
