  'Sebze yemekleri': 'غذاهای سبزی',
  'Sebze, meyve, protein ve tahıllarda çeşitlilik sağlayın. Çocuğu yemek hazırlığına yaşına uygun görevlerle katın; zorla yedirmekten kaçının.': 'در سبزی، میوه، پروتئین و غلات تنوع ایجاد کنید. کودک را با کارهای مناسب سن در آماده کردن غذا شریک کنید؛ از اجبار به خوردن پرهیز کنید.',
  'Sebze, meyve, tam tahıl, baklagil ve yeterli protein içeren dengeli öğünler hazırla.': 'وعده‌های متعادل با سبزیجات، میوه، غلات کامل، حبوبات و پروتئین کافی آماده کنید.',
  'Sebze, meyve, tam tahıl, protein ve süt ürünlerinden çeşitlilik sun. Ne yiyeceğine sen, ne kadar yiyeceğine çocuk karar versin. Şekerli içecekleri ve paketli atıştırmalıkları sınırla.': 'از سبزی، میوه، غلات کامل، پروتئین و لبنیات تنوع بدهید. شما تصمیم می‌گیرید چه خورده شود؛ کودک تصمیم می‌گیرد چقدر. نوشیدنی‌های شیرین و تنقلات بسته‌بندی را محدود کنید.',
  'Sebzeler ve et tamamen yumuşayana kadar 20–25 dakika daha pişirin.': '۲۰–۲۵ دقیقه‌ی دیگر بپزید تا سبزیجات و گوشت کاملاً نرم شوند.',
  'Sebzeler ve et tamamen yumuşayana kadar yaklaşık 25 dakika daha pişirin.': 'حدود ۲۵ دقیقه‌ی دیگر بپزید تا سبزیجات و گوشت کاملاً نرم شوند.',
  'Sebzeler yumuşayıncaya kadar yaklaşık 20 dakika pişirin.': 'حدود ۲۰ دقیقه بپزید تا سبزیجات نرم شوند.',
  'Sebzeleri eşit boyutta doğrayın ki aynı anda pişsin.': 'سبزیجات را هم‌اندازه خرد کنید تا هم‌زمان بپزند.',
  'Sebzeleri ince doğrayın ki balıkla aynı sürede pişsin.': 'سبزیجات را نازک خرد کنید تا هم‌زمان با ماهی بپزند.',
  'Sebzeleri iyice yıkayın.': 'سبزیجات را خوب بشویید.',
  'Sebzeleri soyup eşit kalınlıkta dilimleyin.': 'سبزیجات را پوست بگیرید و هم‌ضخامت ورقه کنید.',
  'Sebzeleri soyup uygun uzunlukta kesin.': 'سبزیجات را پوست بگیرید و به طول مناسب ببرید.',
  'Sebzeleri yağda 8-10 dakika yumuşayana kadar soteleyin.': 'سبزیجات را ۸-۱۰ دقیقه در روغن تفت دهید تا نرم شوند.',
  'Sebzeleri yumuşayana kadar pişirin.': 'سبزیجات را بپزید تا نرم شوند.',
  'Sebzeleri yıkayın.': 'سبزیجات را بشویید.',
  'Sebzeleri, mısırı ve ton balığını kasede birleştirin.': 'سبزیجات، ذرت و تن ماهی را در کاسه ترکیب کنید.',
  'Sebzelerin yarısını her kâğıdın ortasına yayın; alabalıkları tuz ve karabiberle ovup sebzelerin üzerine koyun.': 'نیمی از سبزیجات را وسط هر کاغذ پهن کنید؛ قزل‌آلاها را با نمک و فلفل بمالید و روی سبزیجات بگذارید.',
