  'Sesiniz': 'صدای شما',
  'Sesler uygulama içinde matematiksel olarak üretilir. Brahms Ninnisi (1868) ve “Parla Parla Küçük Yıldız” ezgisi kamu malıdır; “Uyku melodisi” bu uygulama için bestelenmiştir.': 'صداها در برنامه به‌صورت ریاضی تولید می‌شوند. لالایی برامس (۱۸۶۸) و آهنگ «Twinkle, Twinkle, Little Star» در مالکیت عمومی‌اند؛ «ملودی خواب» برای این برنامه ساخته شده است.',
