  'Sezaryen büyük bir karın ameliyatıdır; iyileşme genellikle 6–8 hafta sürer.': 'سزارین جراحی بزرگ شکمی است؛ بهبودی معمولاً ۶–۸ هفته طول می‌کشد.',
  'Sezaryen sonrası ağır kaldırmaktan kaçın; öksürürken karnını yastıkla destekle.': 'پس از سزارین از بلند کردن اجسام سنگین پرهیز کنید؛ هنگام سرفه شکم را با بالش نگه دارید.',
  'Sezaryen sonrası emzirme mümkündür; yan yatarak veya koltuk altı pozisyonu rahat olabilir.': 'شیردهی پس از سزارین ممکن است؛ حالت درازکش به پهلو یا زیربغلی می‌تواند راحت باشد.',
  'Sezaryen sonrası iyileşme': 'بهبودی پس از سزارین',
  'Sezaryen sonrası tam iyileşme 6–8 hafta sürebilir.': 'بهبودی کامل پس از سزارین ممکن است ۶–۸ هفته طول بکشد.',
  'Sezaryen tıbbi gerekliliklerde hayat kurtarıcıdır; büyük bir ameliyat olduğu için iyileşmesi daha uzundur.': 'سزارین وقتی از نظر پزشکی لازم باشد نجات‌بخش است؛ به‌عنوان جراحی بزرگ، بهبودی طولانی‌تری دارد.',
