  'Tava kalabalık olursa balık kızarmaz, haşlanır; gerekirse iki partide pişirin.': 'اگر تابه شلوغ باشد ماهی به‌جای سرخ شدن آب‌پز می‌شود؛ در صورت نیاز در دو نوبت بپزید.',
  'Tavada orta ateşte iki yüzünü kızartın; kalınlığına göre 12–18 dakika pişirin.': 'هر دو طرف را روی حرارت متوسط سرخ کنید؛ بسته به ضخامت ۱۲–۱۸ دقیقه بپزید.',
  'Tavada yağı ısıtıp tavuğu yüksek ateşte renk alana kadar çevirin.': 'روغن را در تابه داغ کنید و مرغ را روی حرارت زیاد تفت دهید تا رنگ بگیرد.',
  'Tavada zeytinyağıyla soğanı 3 dakika yumuşatın, salçayı ekleyip 1 dakika kavurun; rendelenmiş domatesi ve sıcak suyu ilave edip 3 dakika kaynatın.': 'پیاز را ۳ دقیقه در روغن زیتون نرم کنید، رب را اضافه کنید و ۱ دقیقه تفت دهید؛ گوجه‌ی رنده‌شده و آب داغ را بیفزایید و ۳ دقیقه بجوشانید.',
  'Tavuk 74°C iç sıcaklığa ulaşınca ocaktan alın.': 'وقتی دمای داخلی مرغ به ۷۴ درجه رسید از روی حرارت بردارید.',
  'Tavuk bagetleri ve patatesleri yağ, kekik ve biberle harmanlayıp tepsiye tek kat dizin.': 'ران‌ها و سیب‌زمینی‌ها را با روغن، آویشن و فلفل مخلوط کنید و در یک لایه در سینی بچینید.',
  'Tavuk köftesi': 'کوفته‌ی مرغ',
  'Tavuk kıyması, yumurta, galeta unu ve sebzeleri yoğurun.': 'مرغ چرخ‌کرده، تخم‌مرغ، پودر سوخاری و سبزیجات را ورز دهید.',
  'Tavuk suyunu, didiklenmiş tavuğu ve şehriyeyi ekleyin.': 'آب مرغ، مرغ ریش‌شده و رشته را اضافه کنید.',
  'Tavuk tamamen pişmiş olmalı; kemik bulunmamalı.': 'مرغ باید کاملاً پخته باشد؛ نباید استخوانی باقی بماند.',
  'Tavuk ve biberleri şişlere dizip 200°C fırında yaklaşık 20–25 dakika pişirin.': 'مرغ و فلفل‌ها را به سیخ بکشید و در فر ۲۰۰ درجه حدود ۲۰–۲۵ دقیقه بپزید.',
  'Tavuk ve sebzeleri güveç kabına alın; yağ ve suyu ekleyip karıştırın.': 'مرغ و سبزیجات را در ظرف بریزید؛ روغن و آب را اضافه و هم بزنید.',
