  'Terbiyeyi tencereye karıştırarak dökün, hafifçe kaynatın; naneli tereyağı gezdirin.': 'مخلوط را با هم زدن در قابلمه بریزید و کمی بجوشانید؛ کره‌ی نعناعی رویش بریزید.',
