  'Vücut ısısı düşük görünüyor. Bebeği ısıt, ölçümü tekrarla; düşük kalıyorsa ya da bebek halsizse hemen doktora başvur.': 'دمای بدن پایین به نظر می‌رسد. کودک را گرم کنید و دوباره اندازه بگیرید؛ اگر پایین ماند یا کودک بی‌حال است فوراً به پزشک مراجعه کنید.',
  'WHO 0–24 ay referansının 25 ayı da bulunmalı': 'مرجع ۰ تا ۲۴ ماه سازمان جهانی بهداشت باید هر ۲۵ ماه را داشته باشد',
