  'WHO persentili için doğrulanmış CDC/WHO 0–24 ay CSV dosyaları gereklidir. Üstteki yükleme simgesiyle resmi CSV içeriğini panodan içe aktarabilirsiniz. Referans yüklenmeden persentil hesaplanmaz.': 'برای صدک‌های سازمان جهانی بهداشت فایل‌های CSV تأییدشده CDC/WHO برای ۰ تا ۲۴ ماه لازم است. می‌توانید محتوای رسمی CSV را با نماد بارگذاری بالا از کلیپ‌بورد وارد کنید. بدون مرجع صدکی محاسبه نمی‌شود.',
