  'Yaklaşık 6–10 sözcük; basit yönergeleri anlar. Kaşıkla yemekte daha becerikli, inatlaşma başlayabilir.': 'حدود ۶–۱۰ کلمه؛ دستورهای ساده را می‌فهمد. با قاشق بهتر می‌شود؛ لجبازی ممکن است شروع شود.',
