  'Yalnızca izleme, dinleme ve nazik karşılıklı etkileşim kullanın; bebeği zorlamayın. Hareket ve nesne gerektiren adımları uygulamayın.': 'فقط از تماشا، گوش دادن و تعامل ملایم دوطرفه استفاده کنید؛ به نوزاد فشار نیاورید. مراحلی را که نیاز به حرکت یا شیء دارند حذف کنید.',
  'Yalnızca sayıyla başlayan ölçüler oransal hesaplanır. Kesirli, yaklaşık ve metin içindeki ölçüleri kontrol et.': 'فقط مقادیری که با عدد شروع می‌شوند به نسبت محاسبه می‌شوند. مقادیر کسری، تقریبی و درون متن را بررسی کنید.',
  'Yalnızca seçilen çocuğun kayıtları gösterilir. Veriler cihazınızda kalır; kopyalama işlemi panoya aktarır.': 'فقط ثبت‌های کودک انتخاب‌شده نمایش داده می‌شود. داده‌ها روی دستگاه می‌مانند؛ کپی آن‌ها را به کلیپ‌بورد می‌برد.',
