  'Yazdıkların acil değerlendirme gerektirebilecek bir duruma benziyor. Beklemeden 112\'yi ara veya en yakın acil servise başvur. Bu uygulama tanı koymaz ve acil durumda yol gösterici değildir.': 'آنچه نوشتید ممکن است وضعیتی باشد که نیاز به ارزیابی فوری دارد. بدون معطلی با شماره‌ی اورژانس محلی تماس بگیرید یا به نزدیک‌ترین اورژانس بروید. این برنامه تشخیص نمی‌دهد و در اورژانس راهنما نیست.',
  'Yazdığınız soru gönderilir. E-posta ve telefon numaraları otomatik maskelenir; bu tam anonimleştirme değildir. Ad, adres, tahlil veya başka hassas kişisel bilgi yazmayın.': 'پرسشی که می‌نویسید فرستاده می‌شود. ایمیل و شماره تلفن خودکار پوشانده می‌شوند؛ این ناشناس‌سازی کامل نیست. نام، نشانی، نتیجه آزمایش یا دیگر اطلاعات شخصی حساس ننویسید.',
