  'Yağ ve kekikle harmanlayıp tepsiye tek kat dizin.': 'با روغن و آویشن مخلوط کنید و در یک لایه در سینی بچینید.',
  'Yağ ve limonla karıştırarak servis edin.': 'با روغن و لیمو مخلوط کنید و سرو کنید.',
