  'Yaşınıza, sağlık geçmişinize ve risklerinize uygun taramaları aile hekiminizle planlayın. Randevularda sorularınızı ve kullandığınız ilaçları listeleyin.': 'غربالگری‌های مناسب سن، سابقه‌ی سلامت و خطرهایتان را با پزشک خانواده برنامه‌ریزی کنید. سؤال‌ها و داروهایی را که مصرف می‌کنید برای وقت‌ها فهرست کنید.',
  'Yedek alan sayısı geçersiz.': 'تعداد فیلدهای پشتیبان نامعتبر است.',
  'Yedek almak senin elindedir; yedeği parolayla şifrelemen önerilir.': 'پشتیبان‌گیری بر عهده شماست؛ رمزگذاری آن با رمز عبور توصیه می‌شود.',
  'Yedek boyutu sınırı aşıldı (3 MB).': 'حد اندازه پشتیبان (۳ مگابایت) رد شد.',
  'Yedek boş; geri yüklenecek kayıt bulunmuyor. Mevcut kayıtlar korunur.': 'پشتیبان خالی است؛ چیزی برای بازیابی نیست. ثبت‌های موجود حفظ شد.',
