  'Yedek içeriği geçersiz: {0}': 'محتوای پشتیبان نامعتبر است: {0}',
  'Yedek metni çocuğun kişisel sağlık bilgilerini içerir. Panoya kopyalanan içerik diğer uygulamalar tarafından okunabilir. Devam edilsin mi?': 'متن پشتیبان اطلاعات شخصی سلامت کودک را دارد. برنامه‌های دیگر می‌توانند محتوای کلیپ‌بورد را بخوانند. ادامه می‌دهید؟',
  'Yedek oluşturma ve test verisiyle geri yükleme': 'ساخت پشتیبان و بازیابی با داده آزمایشی',
  'Yedek oluşturulamadı: {0}': 'پشتیبان ساخته نشد: {0}',
  'Yedek oluşturulma tarihi bulunmuyor veya geçersiz.': 'تاریخ ساخت پشتیبان موجود نیست یا نامعتبر است.',
  'Yedek oluşturulma tarihi gelecekte görünüyor.': 'به نظر می‌رسد تاریخ ساخت پشتیبان در آینده است.',
  'Yedek parolası (en az 12 karakter)': 'رمز پشتیبان (دست‌کم ۱۲ نویسه)',
  'Yedek parolası en az 12 karakter olmalıdır.': 'رمز پشتیبان باید دست‌کم ۱۲ نویسه باشد.',
  'Yedek parolası en fazla 256 karakter olabilir.': 'رمز پشتیبان حداکثر ۲۵۶ نویسه می‌تواند باشد.',
  'Yedek şifreleme alanları geçersiz.': 'فیلدهای رمزگذاری پشتیبان نامعتبر است.',
  'Yedekleme': 'پشتیبان',
  'Yedekleme ve geri yükleme': 'پشتیبان‌گیری و بازیابی',
  'Yedekler AES-256-GCM ile parola kullanılarak şifrelenir. Parolanızı unutursanız yedeği açamazsınız. Panoya kopyalanan yedek metnini yine de güvenle saklayın. ÖNEMLİ: Bu işlem cihazdaki canlı kayıtları şifrelemez; bulut yedekleme değildir.': 'پشتیبان‌ها با AES-256-GCM و رمز عبور رمزگذاری می‌شوند. اگر رمز را فراموش کنید پشتیبان باز نمی‌شود. با این حال متن پشتیبان کپی‌شده در کلیپ‌بورد را امن نگه دارید. مهم: این کار ثبت‌های فعلی دستگاه را رمزگذاری نمی‌کند؛ پشتیبان ابری نیست.',
