  'Yemek sonrası kısa yürüyüşler kan şekerini düzenler.': 'پیاده‌روی کوتاه پس از غذا به تنظیم قند خون کمک می‌کند.',
  'Yemek ve ek gıda tarifleri': 'دستورهای غذا و غذای کمکی',
  'Yemeklerde tuz yerine baharat ve limon kullan.': 'در آشپزی به‌جای نمک از ادویه و لیمو استفاده کنید.',
  'Yemekleri toplu pişirip porsiyonlayarak dondur.': 'غذاها را یک‌جا بپزید و در وعده‌های جدا منجمد کنید.',
  'Yeni ay': 'ماه نو',
  'Yeni bebek ekle': 'افزودن کودک جدید',
  'Yeni bebek ekle, profiller arasında geçiş yap; günlük ve bakım planı': 'افزودن کودک جدید، جابه‌جایی میان نمایه‌ها؛ دفترچه و برنامه مراقبت',
  'Yeni bebek profili oluştur': 'ساخت نمایه کودک جدید',
  'Yeni becerileri tarih ve kısa gözlemlerle kaydedin; önceki kazanımların kaybını sağlık uzmanıyla görüşün.': 'مهارت‌های جدید را با تاریخ و مشاهدات کوتاه ثبت کنید؛ از دست رفتن مهارت‌های قبلی را با متخصص سلامت در میان بگذارید.',
  'Yeni besin ve öğün günlüğü': 'دفترچه جدید غذا و وعده',
  'Yeni besinleri tek tek tanıt ve tepkileri kaydet.': 'غذاهای جدید را یکی‌یکی معرفی و واکنش‌ها را ثبت کنید.',
  'Yeni besinleri tek tek, birkaç gün arayla tanıt ve tepkileri not et.': 'غذاهای جدید را یکی‌یکی و با فاصله‌ی چند روز شروع کنید و هر واکنشی را یادداشت کنید.',
  'Yeni besinleri, miktarını ve olası belirtilerin ne zaman başladığını kaydedin.': 'غذاهای جدید، مقدارها و زمان شروع هر علامتی را ثبت کنید.',
  'Yeni beslenme kaydı oluştur': 'ساخت ثبت تغذیه جدید',
  'Yeni bir besini kabul etmek için 10–15 kez denemek gerekebilir.': 'ممکن است ۱۰–۱۵ بار امتحان لازم باشد تا غذای جدیدی پذیرفته شود.',
  'Yeni bir ürün kullanırken küçük bir bölgede deneyin; kalıcı kızarıklıkta dermatoloğa danışın.': 'هنگام استفاده از محصول جدید، روی ناحیه‌ی کوچکی امتحان کنید؛ برای قرمزی مداوم به متخصص پوست مراجعه کنید.',
  'Yeni doğan': 'نوزاد',
  'Yeni doğum tarihi, mevcut günlük veya sağlık kayıtlarından sonra olamaz. Önce kayıtları kontrol edin.': 'تاریخ تولد جدید نمی‌تواند پس از ثبت‌های دفترچه یا سلامت موجود باشد. ابتدا ثبت‌ها را بررسی کنید.',
  'Yeni etkinlik': 'رویداد جدید',
  'Yeni hesap oluştur': 'ساخت حساب جدید',
  'Yeni kardeş gelişi büyük çocuk için heyecan kadar kaygı da getirebilir.': 'خواهر یا برادر جدید می‌تواند برای کودک بزرگ‌تر هم هیجان و هم نگرانی بیاورد.',
  'Yeni kardeş ve kıskançlık': 'خواهر یا برادر جدید و حسادت',
  'Yeni kardeş, taşınma gibi büyük değişiklik dönemlerinde başlama.': 'هنگام تغییرات بزرگ مثل آمدن خواهر یا برادر یا اسباب‌کشی شروع نکنید.',
  'Yeni kayıt': 'ثبت جدید',
