  'Yeniden yükle': 'بارگیری دوباره',
  'Yenidoğan': 'نوزاد تازه متولدشده',
  'Yenidoğan akne ve milia (beyaz noktalar) genellikle haftalar içinde kendiliğinden geçer.': 'آکنه‌ی نوزادی و میلیا (نقاط سفید) معمولاً ظرف چند هفته خودبه‌خود برطرف می‌شوند.',
  'Yenidoğan cildinde sivilce, kuru pullanma ve beyaz noktacıklar gibi zararsız değişiklikler sık görülür.': 'تغییرات بی‌خطری مانند لکه، پوسته‌ریزی خشک و نقاط ریز سفید در پوست نوزاد شایع است.',
  'Yenidoğan sarılığı': 'زردی نوزاد',
  'Yenidoğan yoğun bakımda ten tene temas (kanguru bakımı) mümkünse uygula.': 'در صورت امکان در بخش نوزادان تماس پوست با پوست (مراقبت کانگورویی) داشته باشید.',
  'Yenidoğan yüzleri 20–30 cm mesafeden en iyi görür, annesinin sesini ve kokusunu tanır. Emme, yakalama ve irkilme refleksleri vardır.': 'نوزادان چهره‌ها را از فاصله‌ی ۲۰–۳۰ سانتی‌متری بهتر می‌بینند و صدا و بوی مادر را می‌شناسند. رفلکس‌های مکیدن، چنگ زدن و از جا پریدن دارند.',
  'Yenidoğanda gözyaşı kanalı tıkanıklığı sulanma ve hafif çapaklanmaya neden olabilir.': 'انسداد مجرای اشکی در نوزادان می‌تواند باعث اشک‌ریزش و چسبندگی خفیف شود.',
  'Yenidoğanlar ilk günlerde doğum kilosunun yaklaşık %7–10\'unu kaybedebilir; çoğu 10–14 gün içinde geri kazanır.': 'نوزادان ممکن است در روزهای اول حدود ۷–۱۰٪ وزن تولد را از دست بدهند؛ بیشترشان ظرف ۱۰–۱۴ روز آن را جبران می‌کنند.',
  'Yenidoğanların çoğunda ilk günlerde ciltte sarılık görülür; çoğu zararsızdır ama takip gerektirir.': 'بیشتر نوزادان در روزهای اول پوست زردرنگ پیدا می‌کنند؛ معمولاً بی‌خطر است اما نیاز به پیگیری دارد.',
  'Yenidoğanın ilk 48 saatte hiç kaka yapmaması.': 'دفع نکردن هیچ مدفوعی در ۴۸ ساعت اول در نوزاد تازه‌متولد.',
  'Yenidoğanın ilk haftaları': 'هفته‌های اول نوزاد',
  'Yenile': 'تازه‌سازی',
  'Yer fıstığı': 'بادام‌زمینی',
  'Yerde güvenli bir alanda, oturma ve uzanma becerisine göre yetişkin yardımıyla oynayın.': 'روی زمین در جای ایمن و با کمک بزرگسال متناسب با مهارت نشستن و درازکشیدنش بازی کنید.',
  'Yerde güvenli bir hareket rotası hazırlayın.': 'روی زمین مسیر حرکتی ایمنی بسازید.',
  'Yerde güvenli bir minderde serbest hareket, oyuncağı biraz uzağa koyup uzanmasını teşvik etme, şarkılı el oyunları.': 'حرکت آزاد روی تشک ایمن کف اتاق، گذاشتن اسباب‌بازی کمی دورتر برای تشویق به دست دراز کردن، ترانه با بازی‌های دست.',
  'Yerdeki işaretleri takip ederek ilerleyin.': 'با دنبال کردن نشانگرهای روی زمین حرکت کنید.',
  'Yerel bebek ve kadın kayıtları': 'ثبت‌های محلی کودک و زنان',
  'Yerel resmî afet rehberlerini esas alın.': 'از راهنمای رسمی محلی برای بلایا پیروی کنید.',
  'Yerel veri okuma hatası': 'خطا در خواندن داده محلی',
  'Yerel yönetim özeti (ön izleme)': 'خلاصه مدیریت محلی (پیش‌نمایش)',
  'Yerel özet okunamadı.': 'خلاصه محلی خوانده نشد.',
  'Yeryüzü': 'زمین',
  'Yeterli sıvı al ve dinlen.': 'به اندازه‌ی کافی بنوشید و استراحت کنید.',
  'Yeterli sıvı almak sindirim, enerji ve emzirme için önemlidir.': 'نوشیدن کافی برای گوارش، انرژی و شیردهی مهم است.',
  'Yeterli uyku büyüme, öğrenme ve davranış için gereklidir.': 'خواب کافی برای رشد، یادگیری و رفتار ضروری است.',
  'Yeterli ıslak bez olmaması veya kilo alamama.': 'پوشک خیس ناکافی یا وزن نگرفتن.',
  'Yetişkin gözetiminde, yaşa uygun güvenli malzemelerle uygulayın. Çocuk istemezse ara verin.': 'زیر نظر بزرگسال و با مواد ایمن و مناسب سن انجام دهید. اگر کودک نخواست استراحت کنید.',
  'Yetişkin kadınlar için günlük toplam sıvı ihtiyacı yaklaşık 2–2,5 litredir; sıcak havada, gebelikte ve emzirmede artar.': 'زنان بزرگسال روزانه مجموعاً حدود ۲–۲٫۵ لیتر مایعات نیاز دارند؛ در هوای گرم، بارداری و شیردهی بیشتر.',
  'Yetişkin kontrollü su': 'آب زیر نظر بزرگسال',
  'Yetişkin sürekli gözetiminde uygulayın. Küçük parçalar, kopabilen nesneler, ipler ve boğulma riski oluşturan malzemeler kullanmayın. Bebek istemezse durun.': 'زیر نظارت دائمی بزرگسال انجام دهید. از قطعات کوچک، اشیای جداشدنی، نخ یا موادی که خطر خفگی دارند استفاده نکنید. اگر نوزاد نخواست متوقف کنید.',
  'Yetişkinlerde 21–35 gün arası döngü olağan kabul edilir.': 'در بزرگسالان چرخه‌ی ۲۱–۳۵ روزه طبیعی محسوب می‌شود.',
  'Yetki kontrollü moderasyon': 'نظارت کنترل‌شده با مجوز',
  'Yetkiler, şikâyet akışları, spam koruması ve gerçek bildirim testleri gerekli. Telefon push bildirimi yok.': 'مجوزها، مسیرهای گزارش، محافظت از هرزنامه و آزمون واقعی اعلان لازم است. اعلان push وجود ندارد.',
  'Yeşil mercimek yemeği': 'خوراک عدس سبز',
  'Yeşil, kanlı veya kahve telvesi görünümünde kusma.': 'استفراغ سبز، خونی یا شبیه تفاله‌ی قهوه.',
  'Yeşillikleri yıkadıktan sonra iyice kurutun; sos daha iyi tutunur.': 'سبزی‌های برگی را پس از شستن خوب خشک کنید؛ سس بهتر به آن‌ها می‌چسبد.',
