  'Yorgunluk geri dönebilir; huzursuz bacak hissi olabilir.': 'خستگی ممکن است برگردد؛ ممکن است سندرم پای بی‌قرار داشته باشید.',
  'Yorgunluk ve sık idrara çıkma artar.': 'خستگی و تکرر ادرار بیشتر می‌شود.',
  'Yorgunluk, açlık ve aşırı uyarılma nöbetleri tetikleyebilir.': 'خستگی، گرسنگی و تحریک بیش از حد می‌توانند قشقرق را برانگیزند.',
  'Yorgunluk, meme hassasiyeti ve sık idrara çıkma başlayabilir.': 'خستگی، حساسیت پستان و تکرر ادرار ممکن است شروع شود.',
  'Yorgunluk, solukluk, nefes darlığı, saç dökülmesi ve tırnak kırılması belirtiler arasındadır.': 'خستگی، رنگ‌پریدگی، تنگی نفس، ریزش مو و شکنندگی ناخن از نشانه‌ها هستند.',
  'Yorgunluk, uyuşma-karıncalanma, solukluk; çocukta büyüme geriliği.': 'خستگی، بی‌حسی یا گزگز، رنگ‌پریدگی؛ در کودکان رشد ضعیف.',
  'Yoğun kanama, ateş veya karın ağrısı.': 'خونریزی شدید، تب یا درد شکم.',
  'Yoğun kanama, sürekli ve şiddetli karın ağrısı.': 'خونریزی شدید، درد شکم دائمی و شدید.',
  'Yoğun veya uzun süren sıkıntıda destek alın.': 'برای پریشانی شدید یا طولانی حمایت بگیرید.',
  'Yoğurdu ezilmiş sarımsakla karıştırıp pancarı ekleyin.': 'ماست را با سیر له‌شده مخلوط کنید و چغندر را اضافه کنید.',
  'Yoğurdu ezilmiş sarımsakla çırpın.': 'ماست را با سیر له‌شده هم بزنید.',
  'Yoğurdu servis kasesine alın.': 'ماست را در کاسه‌ی سرو بریزید.',
  'Yoğurt': 'ماست',
  'Yoğurt ve yumurtayı çırpıp karnabaharlarla harmanlayın.': 'ماست و تخم‌مرغ را هم بزنید و با گل‌کلم مخلوط کنید.',
  'Yoğurt ve zeytinyağını çırpıp sebzelerle harmanlayın.': 'ماست و روغن زیتون را هم بزنید و با سبزیجات مخلوط کنید.',
  'Yoğurt, yağ ve kekikle tavuğu karıştırıp buzdolabında 30 dakika bekletin.': 'مرغ را با ماست، روغن و آویشن مخلوط کنید و ۳۰ دقیقه در یخچال بگذارید.',
  'Yoğurt, yağ, yumurta beyazı, tuz ve kabartma tozunu karıştırın.': 'ماست، روغن، سفیده، نمک و بکینگ پودر را مخلوط کنید.',
  'Yoğurt, yumurta sarısı ve unu ayrı kapta çırpın.': 'ماست، زرده و آرد را در ظرفی جدا هم بزنید.',
  'Yoğurtla ezilmiş sarımsağı ayrı kapta karıştırın.': 'ماست را با سیر له‌شده در ظرفی جدا مخلوط کنید.',
  'Yoğurtla karıştırın.': 'با ماست مخلوط کنید.',
  'Yoğurtlu dereotlu sos ve yeşil salata ile servis edin.': 'با سس ماست و شوید و سالاد سبز سرو کنید.',
  'Yoğurtlu granola': 'گرانولا با ماست',
  'Yoğurtlu meyve kasesi': 'کاسه‌ی میوه با ماست',
  'Yoğurtlu tavuk': 'مرغ با ماست',
  'Yoğurtlu yulaf': 'جو دوسر با ماست',
  'Yufkaları tepsiye serip her katı sosla ıslatın; iki yufkanın üzerine harcı yayın, kalan yufkaları da sosla ıslatarak kapatın.': 'یوفکاها را در سینی پهن کنید و هر لایه را با سس خیس کنید؛ مواد را روی دو ورق پخش کنید و با باقی ورق‌های خیس‌شده با سس بپوشانید.',
  'Yukarıdaki kutulardan birine dokunarak ilk ölçümünü ekle.': 'برای افزودن اولین اندازه روی یکی از کادرهای بالا بزنید.',
  'Yulaf, süt ve elmayı küçük tencereye alın.': 'جو دوسر، شیر و سیب را در قابلمه‌ی کوچک بریزید.',
  'Yulafı suyla iyice pişirin.': 'جو دوسر را با آب خوب بپزید.',
  'Yulafın olası çapraz bulaşmasını kontrol edin.': 'جو دوسر را از نظر آلودگی متقاطع احتمالی بررسی کنید.',
  'Yulafın çapraz bulaşmasını kontrol edin.': 'جو دوسر را از نظر آلودگی متقاطع بررسی کنید.',
  'Yumurta': 'تخم‌مرغ',
  'Yumurta akı ve sarısı tamamen pişene kadar fırınlayın.': 'در فر بپزید تا سفیده و زرده کاملاً پخته شوند.',
  'Yumurta içerir.': 'حاوی تخم‌مرغ است.',
  'Yumurta sarısı sürüp 35 dakika kızarana kadar pişirin.': 'زرده‌ی تخم‌مرغ رویش بمالید و ۳۵ دقیقه بپزید تا طلایی شود.',
  'Yumurta tamamen pişene kadar karıştırın.': 'هم بزنید تا تخم‌مرغ کاملاً بپزد.',
  'Yumurta tamamen pişmiş olmalı; yeni alerjenleri dikkatle tanıtın.': 'تخم‌مرغ باید کاملاً پخته باشد؛ آلرژن‌های جدید را با احتیاط معرفی کنید.',
  'Yumurta ve sütü çatalla çırpın.': 'تخم‌مرغ و شیر را با چنگال هم بزنید.',
  'Yumurta ve sütü çırpıp ıspanağı ekleyin.': 'تخم‌مرغ و شیر را هم بزنید و اسفناج را اضافه کنید.',
  'Yumurta, süt ve unu çırpıp sebzeleri karıştırın.': 'تخم‌مرغ، شیر و آرد را هم بزنید و سبزیجات را مخلوط کنید.',
  'Yumurta, süt, kalan yağ, tuz ve karabiberi çırparak sos hazırlayın.': 'تخم‌مرغ، شیر، باقی روغن، نمک و فلفل را هم بزنید تا سس آماده شود.',
  'Yumurta, süt, un ve kabartma tozuyla karıştırın.': 'با تخم‌مرغ، شیر، آرد و بکینگ پودر مخلوط کنید.',
  'Yumurtalar tamamen piştiğinde sıcak servis edin.': 'وقتی تخم‌مرغ کاملاً پخت، داغ سرو کنید.',
  'Yumurtaları kırıp karıştırın.': 'تخم‌مرغ‌ها را بشکنید و هم بزنید.',
  'Yumurtayla karıştırın.': 'با تخم‌مرغ مخلوط کنید.',
  'Yumurtayı ekleyin.': 'تخم‌مرغ را اضافه کنید.',
  'Yumurtlama döneminde berrak, kaygan akıntı ve hafif kasık ağrısı olabilir.': 'حوالی تخمک‌گذاری ممکن است ترشح شفاف و لغزنده و درد خفیف لگن وجود داشته باشد.',
  'Yumurtlama ve verimli dönem, ortalama döngü süresine göre yaklaşık hesaplanır. Doğum kontrolü veya gebelik planlaması için güvenilir bir yöntem değildir; tıbbi değerlendirme yerine geçmez.': 'تخمک‌گذاری و دوره باروری از میانگین طول چرخه شما تخمین زده می‌شود. روش مطمئنی برای پیشگیری یا برنامه‌ریزی بارداری نیست و جای ارزیابی پزشکی را نمی‌گیرد.',
  'Yumurtlama çoğunlukla bir sonraki adetten yaklaşık 14 gün önce olur.': 'تخمک‌گذاری معمولاً حدود ۱۴ روز پیش از قاعدگی بعدی رخ می‌دهد.',
  'Yumurtlama çoğunlukla bu haftanın sonuna doğru olur; döllenme yumurtlamadan sonraki yaklaşık bir gün içinde gerçekleşebilir.': 'تخمک‌گذاری معمولاً اواخر این هفته رخ می‌دهد؛ لقاح ممکن است حدود یک روز پس از تخمک‌گذاری انجام شود.',
  'Yumuşak Kitap': 'کتاب پارچه‌ای',
