  'Yumuşak banyo havlusu.': 'حوله‌ی حمام نرم.',
  'Yumuşak bloklar, kapaklı kutular, el sallama ve alkış oyunu. Günlük işleri anlatarak konuşmayı sürdür.': 'مکعب‌های نرم، جعبه‌های دردار، بازی‌های دست تکان دادن و دست زدن. کارهای روزمره را بازگو کنید.',
