  'Yuva, kuş yuvası': 'لانه، آشیانه‌ی پرنده',
  'Yuvarlak ve köşeli şekilleri birlikte inceleyin.': 'اشکال گرد و گوشه‌دار را با هم بررسی کنید.',
  'Yuvarlanma başladığı için alt değiştirme masasında elini bebekten ayırma. Küçük nesneleri, düğme pilleri ve ipleri ulaşamayacağı yerde tut.': 'حالا که غلت زدن شروع شده، روی میز تعویض دستتان را روی نوزاد نگه دارید. اشیای کوچک، باتری‌های سکه‌ای و سیم‌ها را دور از دسترس نگه دارید.',
  'Yuvarlanır (çoğunlukla yüzüstüden sırtüstüne); nesneleri ağzına götürür. Adına tepki vermeye başlar, ses tonlarını ayırt eder.': 'غلت می‌زند (معمولاً از شکم به پشت)؛ اشیا را به دهان می‌برد. شروع به واکنش به نامش می‌کند، لحن صداها را تشخیص می‌دهد.',
  'Yönetim verilerine erişilemedi. Yönetici yetkinizi, oturumunuzu ve sunucu kurulumunu kontrol edin.': 'دسترسی به داده‌های مدیریت ممکن نشد. مجوز مدیر، جلسه و راه‌اندازی سرور را بررسی کنید.',
  'Yönetim özeti • Ön izleme': 'خلاصه مدیریت • پیش‌نمایش',
  'Yüce adların nuru': 'نور نام‌های والا',
  'Yüce han': 'خان والا',
  'Yüce, yüksek': 'والا، بلندمرتبه',
  'Yüce; Osmanlı padişahı': 'والا؛ سلطان عثمانی',
  'Yüklenen referanslar yalnızca bu ekran açıkken tutulur. 0–24 ay aylık WHO persentilleri bilgi amaçlıdır; tıbbi değerlendirme değildir.': 'مرجع‌های بارگیری‌شده فقط تا باز بودن این صفحه نگه داشته می‌شوند. صدک‌های ماهانه ۰ تا ۲۴ ماه سازمان جهانی بهداشت اطلاع‌رسانی‌اند؛ ارزیابی پزشکی نیستند.',
  'Yüksek ateş, aşırı halsizlik veya uyandırmakta güçlük.': 'تب بالا، ضعف شدید یا دشواری در بیدار شدن.',
  'Yüksek ateş, nefes darlığı, bayılma, nöbet: 112.': 'تب بالا، تنگی نفس، غش، تشنج: با شماره‌ی اورژانس محلی تماس بگیرید.',
  'Yüksek sarılık değerleri tedavi edilmezse zarar verebilir; bu nedenle kontrol önemlidir.': 'زردی بسیار بالا در صورت درمان نشدن می‌تواند آسیب‌زا باشد، پس معاینات مهم‌اند.',
  'Yüksek yüzeylerde yalnız bırakmayın. Küçük parçaları, kabloları, ilaçları ve sıcak içecekleri erişimden uzak tutun; uygun oto koltuğu kullanın.': 'روی سطوح بلند تنهایش نگذارید. قطعات کوچک، سیم‌ها، داروها و نوشیدنی‌های داغ را دور از دسترس نگه دارید؛ از صندلی ماشین مناسب استفاده کنید.',
  'Yüksek, yüce': 'بلند، والا',
  'Yüksekten düşme, bilinç değişikliği veya kusma.': 'افتادن از ارتفاع، تغییر هوشیاری یا استفراغ.',
  'Yükseliş': 'عروج',
  'Yükseliş; merdiven': 'معراج؛ نردبان',
  'Yükselme, terakki': 'ترقی، پیشرفت',
  'Yükselmek': 'بالا رفتن',
  'Yürüme için güvenli alan, basit şekil yerleştirme, birlikte şarkı ve kitap. 1 yaş kontrolüne git.': 'فضای ایمن برای راه رفتن، جورچین ساده‌ی اشکال، ترانه و کتاب با هم. به معاینه‌ی ۱ سالگی بروید.',
  'Yürüme, ilk kelimeler ve bağımsızlık isteği bu dönemin öne çıkan özellikleridir.': 'راه رفتن، اولین کلمات و میل به استقلال نکات برجسته‌ی این مرحله‌اند.',
  'Yürüteç kullanma: düşme ve yaralanma riskini artırır.': 'از روروئک استفاده نکنید: خطر افتادن و آسیب را افزایش می‌دهد.',
  'Yürüyüş, yüzme, sabit bisiklet ve gebe yogası güvenli seçeneklerdir.': 'پیاده‌روی، شنا، دوچرخه‌ی ثابت و یوگای بارداری گزینه‌های ایمنی هستند.',
  'Yürüyüşle başlayıp yavaş yavaş artır.': 'با پیاده‌روی شروع کنید و آرام‌آرام بیشترش کنید.',
  'Yüz ifadeleri başlayabilir; vücudu ince tüylerle (lanugo) kaplanmaya başlar.': 'حالت‌های چهره ممکن است شروع شود؛ بدن با موهای ظریف (لانوگو) پوشیده می‌شود.',
  'Yüz ifadelerini keşfet': 'کشف حالت‌های چهره',
  'Yüz temizliği, nemlendirme ve güneşten korunmayı üç kısa adıma bölün. Yeni ürünleri tek tek ekleyerek cildinizin tepkisini gözlemleyin.': 'پاک‌سازی صورت، مرطوب کردن و محافظت از آفتاب را در سه گام کوتاه انجام دهید. محصولات جدید را یکی‌یکی اضافه کنید و واکنش پوستتان را ببینید.',
  'Yüz ve ellerde ani şişlik, nefes darlığı: hemen başvur.': 'تورم ناگهانی صورت و دست‌ها، تنگی نفس: فوراً کمک بگیرید.',
  'Yüz-dil şişmesi, solunum güçlüğü veya baygınlık gibi bulgular acil değerlendirme gerektirir.': 'نشانه‌هایی مثل تورم صورت یا زبان، دشواری تنفس یا غش نیاز به ارزیابی فوری دارند.',
  'Yüzey temizleyici': 'پاک‌کننده‌ی سطوح',
  'Yıkama talimatı': 'دستور شستشو',
  'Yıkama ve ütü talimatlarını kontrol edin. Hassas kumaşları uygun programda yıkayın; kurutma talimatlarına uyun.': 'دستورهای شستشو و اتو را بررسی کنید. پارچه‌های ظریف را با برنامه‌ی مناسب بشویید؛ از دستورهای خشک کردن پیروی کنید.',
  'Yıkanabilirlik': 'قابلیت شستشو',
  'Yıkanmış bulguru ekleyip 1 dakika karıştırın.': 'بلغور شسته را اضافه کنید و ۱ دقیقه هم بزنید.',
  'Yıkanmış pirinci ve suyu ilave edin.': 'برنج شسته و آب را اضافه کنید.',
  'Yıkayıp soyun.': 'بشویید و پوست بگیرید.',
  'Yılan yavrusu; Osman Gazi': 'بچه‌مار؛ عثمان غازی',
  'Yılda 2–3\'ten fazla tekrarlayan enfeksiyon.': 'بیش از ۲–۳ عفونت تکراری در سال.',
  'Yılda bir genel kontrol; doktorunun önerisine göre.': 'یک معاینه عمومی در سال؛ طبق توصیه پزشک.',
  'Yılda bir; büyüyen, renk değiştiren ya da kanayan ben için beklemeden.': 'سالی یک بار؛ و بی‌درنگ اگر خالی بزرگ شود، تغییر رنگ دهد یا خونریزی کند.',
  'Yıldız': 'ستاره',
  'Yıllar içinde artan şiddetli ağrı endometriozis gibi durumların belirtisi olabilir.': 'درد شدیدی که طی سال‌ها بدتر می‌شود می‌تواند نشانه‌ی بیماری‌هایی مثل اندومتریوز باشد.',
  'Yılmayan': 'خستگی‌ناپذیر',
  'Yılın dokuzuncu ayı': 'ماه نهم سال',
  'Yılın dördüncü ayı': 'ماه چهارم سال',
  'Yılın onuncu ayı; ekin': 'ماه دهم سال؛ کِشت',
  'Zafer': 'پیروزی',
  'Zamanlayıcı kapalı – sürekli tekrar eder': 'زمان‌سنج خاموش – تکرار پیوسته',
  'Zamanlayıcı: Sol {0}, Sağ {1}': 'زمان‌سنج: چپ {0}، راست {1}',
