  'İpucu: takvimde bir güne dokunarak da adet başlangıcı ekleyebilirsin.': 'نکته: می‌توانید با زدن روی یک روز در تقویم هم شروع قاعدگی را ثبت کنید.',
  'İri ve sert parçalar bırakmayın.': 'تکه‌های بزرگ و سفت باقی نگذارید.',
  'İshal dönemlerinde ve antibiyotik kullanımında pişik sıklaşır.': 'سوختگی پوشک هنگام اسهال و مصرف آنتی‌بیوتیک شایع‌تر می‌شود.',
  'İshal ve kusma': 'اسهال و استفراغ',
  'İshal ve kusma çoğu zaman viral enfeksiyonlara bağlıdır ve birkaç günde geçer.': 'اسهال و استفراغ معمولاً ناشی از عفونت‌های ویروسی است و ظرف چند روز برطرف می‌شود.',
