  'İsteğini doğum ekibine önceden ilet.': 'خواسته‌هایتان را از قبل به تیم زایمان بگویید.',
  'İtme oyuncakları (sağlam, devrilmeyen), top yuvarlama, hayvan sesleri taklidi.': 'اسباب‌بازی‌های هل‌دادنی (محکم، واژگون‌نشدنی)، غلتاندن توپ، تقلید صدای حیوانات.',
  'İyi Hisset': 'حال خوب',
  'İyi ki buradasın!': 'چه خوب که اینجایید!',
  'İyi ki buradasın!\nBebek profilini ekleyerek başla.': 'چه خوب که اینجایید!\nبا افزودن نمایه کودکتان شروع کنید.',
  'İyi pişirin, uygun yumuşak parçalara bölün.': 'خوب بپزید و به تکه‌های نرم مناسب ببرید.',
