  'İyi planlanmış bitkisel beslenme her yaşta mümkündür; bazı besin ögelerine dikkat gerekir.': 'تغذیه‌ی گیاهی خوب برنامه‌ریزی‌شده در هر سنی ممکن است؛ برخی مواد مغذی نیاز به توجه دارند.',
  'İyi, yararlı; bir peygamber': 'نیک، سودمند؛ یکی از پیامبران',
  'İyice ezip taze sunun.': 'خوب له کنید و تازه بدهید.',
