  'İzinleri ve sessiz saatleri yönet': 'مدیریت مجوزها و ساعات سکوت',
  'İç mekân hava filtreleme seçeneği.': 'گزینه‌ای برای فیلتر کردن هوای داخل.',
  'İç sıcaklık 74°C olduğunda ocaktan alın; 3 dakika dinlendirin.': 'وقتی دمای داخلی ۷۴ درجه شد از روی حرارت بردارید؛ ۳ دقیقه بگذارید بماند.',
  'İç, gizli': 'درون، نهان',
  'İçecek': 'نوشیدنی',
  'İçecek sıcaklığını koruyan kap.': 'ظرفی که دمای نوشیدنی را حفظ می‌کند.',
  'İçecekler': 'نوشیدنی‌ها',
  'İçerik': 'محتویات',
  'İçerik etiketini inceleyin.': 'برچسب مواد تشکیل‌دهنده را بررسی کنید.',
  'İçerikler bilgilendirme amaçlıdır, tıbbi tavsiye değildir. Döngü tahminleri yaklaşıktır ve doğum kontrolü için kullanılmamalıdır. Acil durumda 112\'yi ara.': 'محتوا اطلاع‌رسانی است نه توصیه پزشکی. پیش‌بینی‌های چرخه تقریبی‌اند و نباید برای پیشگیری از بارداری استفاده شوند. در شرایط اضطراری با شماره اورژانس محلی تماس بگیرید.',
  'İçerikler genel bilgilendirme amaçlıdır. Sağlıkla ilgili konularda uzman görüşü alın.': 'محتوا برای اطلاعات عمومی است. در مسائل سلامت از متخصص مشورت بگیرید.',
  'İçeriği kaldır': 'حذف محتوا',
  'İçeriği kaldır?': 'محتوا حذف شود؟',
  'İçi tamamen pişene kadar pişirin.': 'بپزید تا کاملاً پخته شود.',
  'İçme suyu': 'آب آشامیدنی',
