  'İş Kanunu kapsamında doğum öncesi ve sonrası toplam 16 hafta (çoğul gebelikte 18 hafta) ücretli doğum izni vardır.': 'در ترکیه، قانون کار مجموعاً ۱۶ هفته مرخصی زایمان با حقوق پیش و پس از تولد می‌دهد (برای چندقلویی ۱۸ هفته).',
