  'İşitme ile ilgili şüphe: işitme testi yaptır.': 'هر تردیدی درباره‌ی شنوایی: آزمون شنوایی بدهید.',
  'İşitme sorunları konuşma gecikmesinin önemli bir nedenidir.': 'مشکلات شنوایی علت مهمی برای تأخیر گفتار است.',
